--
-- Name: purge_expired(interval); Type: PROCEDURE; Schema: audit; Owner: smartspare_owner
--

CREATE PROCEDURE audit.purge_expired(IN p_retention interval DEFAULT '180 days'::interval)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT c.oid::regclass AS part,
               (regexp_match(pg_get_expr(c.relpartbound, c.oid), 'TO \(''([^'']+)''\)'))[1]::timestamptz AS upper_bound
        FROM pg_inherits i
        JOIN pg_class c ON c.oid = i.inhrelid
        WHERE i.inhparent = 'audit.audit_log'::regclass
          AND pg_get_expr(c.relpartbound, c.oid) <> 'DEFAULT'
    LOOP
        IF r.upper_bound <= now() - p_retention THEN
            EXECUTE format('ALTER TABLE audit.audit_log DETACH PARTITION %s', r.part);
            EXECUTE format('DROP TABLE %s', r.part);
            RAISE NOTICE 'Dropped expired audit partition %', r.part;
        END IF;
    END LOOP;
END $$;


ALTER PROCEDURE audit.purge_expired(IN p_retention interval) OWNER TO smartspare_owner;

--
-- Name: PROCEDURE purge_expired(IN p_retention interval); Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON PROCEDURE audit.purge_expired(IN p_retention interval) IS 'Drops audit partitions older than the retention period (default 180 days). Run monthly by Quartz.NET.';


--
-- Name: trg_row_audit(); Type: FUNCTION; Schema: audit; Owner: smartspare_owner
--

CREATE FUNCTION audit.trg_row_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_old      jsonb;
    v_new      jsonb;
    v_excluded text[] := ARRAY['updated_at'] || coalesce(TG_ARGV::text[], '{}');
    v_changed  text[];
    v_id       text;
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') THEN v_old := to_jsonb(OLD) - v_excluded; END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') THEN v_new := to_jsonb(NEW) - v_excluded; END IF;

    IF TG_OP = 'UPDATE' THEN
        SELECT array_agg(n.key ORDER BY n.key) INTO v_changed
        FROM jsonb_each(v_new) n
        WHERE n.value IS DISTINCT FROM v_old -> n.key;
        IF v_changed IS NULL THEN RETURN NULL; END IF;     -- nothing relevant changed
        -- keep only the changed columns
        SELECT jsonb_object_agg(k, v_old -> k), jsonb_object_agg(k, v_new -> k)
          INTO v_old, v_new
        FROM unnest(v_changed) AS k;
    END IF;

    v_id := coalesce(v_new, v_old) ->> 'id';
    IF v_id IS NULL THEN  -- composite keys: concatenate *_id columns
        SELECT string_agg(value, '|' ORDER BY key) INTO v_id
        FROM jsonb_each_text(coalesce(to_jsonb(NEW), to_jsonb(OLD)))
        WHERE key LIKE '%\_id' ESCAPE '\';
    END IF;

    INSERT INTO audit.audit_log (user_id, action, table_name, record_id, old_values, new_values, changed_columns, reason)
    VALUES (nullif(current_setting('app.user_id', true), '')::uuid,
            TG_OP, TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, coalesce(v_id, '?'),
            v_old, v_new, v_changed,
            nullif(current_setting('app.reason', true), ''));
    RETURN NULL;
END $$;


ALTER FUNCTION audit.trg_row_audit() OWNER TO smartspare_owner;

--
-- Name: FUNCTION trg_row_audit(); Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON FUNCTION audit.trg_row_audit() IS 'AFTER ROW trigger writing changed columns into audit.audit_log; arguments = excluded columns (PII, secrets).';


--
-- Name: cancel_service_order(bigint, text); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.cancel_service_order(p_service_order_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('SERVICE_ENGINEER', 'BRAND_MANAGER', 'ADMINISTRATOR');
BEGIN
    PERFORM 1 FROM fleet.service_order WHERE id = p_service_order_id FOR UPDATE;
    UPDATE inventory.stock_reservation r SET status = 'released'
      FROM fleet.service_order_line l
     WHERE l.service_order_id = p_service_order_id AND r.service_order_line_id = l.id AND r.status IN ('soft', 'firm');
    UPDATE fleet.service_order SET status = 'cancelled', cancel_reason = p_reason WHERE id = p_service_order_id;
END $$;


ALTER FUNCTION fleet.cancel_service_order(p_service_order_id bigint, p_reason text) OWNER TO smartspare_owner;

--
-- Name: complete_service_order(bigint, numeric); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.complete_service_order(p_service_order_id bigint, p_engine_hours numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user  uuid := util.require_role('SERVICE_ENGINEER', 'ADMINISTRATOR');
    v_so    fleet.service_order;
    v_line  record;
BEGIN
    SELECT * INTO v_so FROM fleet.service_order WHERE id = p_service_order_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Service order % not found', p_service_order_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_so.status NOT IN ('draft', 'parts_reserved', 'in_progress') THEN
        RAISE EXCEPTION 'Service order % is %', v_so.number, v_so.status USING ERRCODE = 'SS300';
    END IF;

    FOR v_line IN
        SELECT l.id, l.part_id, l.qty_required - l.qty_issued AS qty, p.unit_cost
        FROM fleet.service_order_line l JOIN catalog.part p ON p.id = l.part_id
        WHERE l.service_order_id = p_service_order_id AND l.qty_required > l.qty_issued
        ORDER BY l.part_id
    LOOP
        UPDATE inventory.stock_reservation SET status = 'consumed'
         WHERE service_order_line_id = v_line.id AND status IN ('soft', 'firm');
        INSERT INTO inventory.stock_movement (occurred_at, warehouse_id, part_id, movement_type_code, quantity,
                                              unit_cost, service_order_line_id, created_by)
        VALUES (now(), v_so.warehouse_id, v_line.part_id, 'ISSUE_SERVICE', v_line.qty, v_line.unit_cost, v_line.id, v_user);
        UPDATE fleet.service_order_line SET qty_issued = qty_required WHERE id = v_line.id;
    END LOOP;

    UPDATE fleet.service_order
       SET status = 'completed', completed_at = now(), completed_engine_hours = p_engine_hours
     WHERE id = p_service_order_id;
END $$;


ALTER FUNCTION fleet.complete_service_order(p_service_order_id bigint, p_engine_hours numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION complete_service_order(p_service_order_id bigint, p_engine_hours numeric); Type: COMMENT; Schema: fleet; Owner: smartspare_owner
--

COMMENT ON FUNCTION fleet.complete_service_order(p_service_order_id bigint, p_engine_hours numeric) IS 'Consumes the kit reservations, issues parts (ISSUE_SERVICE = demand) and closes the order.';


--
-- Name: create_service_order_draft(bigint, integer, numeric); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.create_service_order_draft(p_machine_id bigint, p_plan_id integer, p_due_engine_hours numeric) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user    uuid := util.require_role('SERVICE_ENGINEER', 'BRAND_MANAGER', 'ADMINISTRATOR');
    v_wh      smallint;
    v_hours   numeric;
    v_so      bigint;
    v_line    record;
    v_avail   numeric;
    v_qty     numeric;
    v_all     boolean := true;
    v_lines   integer := 0;
BEGIN
    SELECT home_warehouse_id, current_engine_hours INTO v_wh, v_hours
    FROM fleet.machine WHERE id = p_machine_id;

    INSERT INTO fleet.service_order (machine_id, maintenance_plan_id, warehouse_id, due_engine_hours, trigger_engine_hours, created_by)
    VALUES (p_machine_id, p_plan_id, v_wh, p_due_engine_hours, v_hours, v_user)
    RETURNING id INTO v_so;

    INSERT INTO fleet.service_order_line (service_order_id, part_id, qty_required)
    SELECT v_so, k.part_id, k.quantity
    FROM fleet.maintenance_plan_part k WHERE k.maintenance_plan_id = p_plan_id;

    FOR v_line IN
        SELECT l.id, l.part_id, l.qty_required FROM fleet.service_order_line l
        WHERE l.service_order_id = v_so ORDER BY l.part_id
    LOOP
        v_lines := v_lines + 1;
        SELECT b.available_qty INTO v_avail FROM inventory.stock_balance b
        WHERE b.warehouse_id = v_wh AND b.part_id = v_line.part_id FOR UPDATE;
        v_qty := least(coalesce(v_avail, 0), v_line.qty_required);
        IF v_qty > 0 THEN
            INSERT INTO inventory.stock_reservation (warehouse_id, part_id, quantity, status, expires_at, service_order_line_id, created_by)
            VALUES (v_wh, v_line.part_id, v_qty, 'soft', now() + interval '7 days', v_line.id, v_user);
        END IF;
        IF v_qty < v_line.qty_required THEN v_all := false; END IF;   -- shortage -> visible in fleet.v_service_kit_shortage
    END LOOP;

    IF v_lines > 0 AND v_all THEN
        UPDATE fleet.service_order SET status = 'parts_reserved' WHERE id = v_so;
    END IF;
    RETURN v_so;
END $$;


ALTER FUNCTION fleet.create_service_order_draft(p_machine_id bigint, p_plan_id integer, p_due_engine_hours numeric) OWNER TO smartspare_owner;

--
-- Name: fn_maintenance_due(bigint, numeric); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.fn_maintenance_due(p_machine_id bigint, p_horizon_hours numeric DEFAULT 50) RETURNS TABLE(maintenance_plan_id integer, plan_name character varying, interval_hours integer, effective_interval numeric, due_engine_hours numeric, current_engine_hours numeric, remaining_hours numeric, is_overdue boolean)
    LANGUAGE sql STABLE
    AS $$
    WITH m AS (
        SELECT m.id, m.model_id, m.current_engine_hours, oc.interval_factor,
               (SELECT r.reading_hours FROM fleet.engine_hours_reading r
                WHERE r.machine_id = m.id ORDER BY r.read_at LIMIT 1) AS first_reading
        FROM fleet.machine m
        JOIN ref.operating_condition oc ON oc.id = m.operating_condition_id
        WHERE m.id = p_machine_id AND m.status = 'active'
    ), p AS (
        SELECT mp.id, mp.name, mp.interval_hours,
               round(mp.interval_hours * m.interval_factor, 1) AS eff,   -- F5: condition shortens interval
               m.current_engine_hours,
               coalesce(
                   (SELECT max(so.due_engine_hours) FROM fleet.service_order so
                    WHERE so.machine_id = m.id AND so.maintenance_plan_id = mp.id AND so.status <> 'cancelled'),
                   -- thresholds before the first known reading are unknown history: not drafted
                   floor(coalesce(m.first_reading, 0) / round(mp.interval_hours * m.interval_factor, 1))
                       * round(mp.interval_hours * m.interval_factor, 1)) AS last_due
        FROM m JOIN fleet.maintenance_plan mp ON mp.model_id = m.model_id AND mp.is_active
    )
    SELECT p.id, p.name, p.interval_hours, p.eff, d.due, p.current_engine_hours,
           d.due - p.current_engine_hours, p.current_engine_hours >= d.due
    FROM p
    -- next threshold after the last one served; if several were skipped, only the latest crossed one
    CROSS JOIN LATERAL (SELECT greatest((floor(p.last_due / p.eff) + 1) * p.eff,
                                        floor(p.current_engine_hours / p.eff) * p.eff) AS due) d
    WHERE d.due > 0 AND d.due - p.current_engine_hours <= p_horizon_hours
    ORDER BY d.due - p.current_engine_hours, p.interval_hours DESC
$$;


ALTER FUNCTION fleet.fn_maintenance_due(p_machine_id bigint, p_horizon_hours numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION fn_maintenance_due(p_machine_id bigint, p_horizon_hours numeric); Type: COMMENT; Schema: fleet; Owner: smartspare_owner
--

COMMENT ON FUNCTION fleet.fn_maintenance_due(p_machine_id bigint, p_horizon_hours numeric) IS 'Planned services of a machine due within the horizon (effective interval = OEM interval x condition factor).';


--
-- Name: log_engine_hours(bigint, numeric, timestamp with time zone, fleet.reading_source); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.log_engine_hours(p_machine_id bigint, p_reading_hours numeric, p_read_at timestamp with time zone DEFAULT now(), p_source fleet.reading_source DEFAULT 'manual'::fleet.reading_source) RETURNS TABLE(service_order_id bigint, service_order_number character varying, due_engine_hours numeric, fully_reserved boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
    v_user uuid := util.require_role('SERVICE_ENGINEER', 'ADMINISTRATOR');
    v_due  record;
    v_so   bigint;
BEGIN
    INSERT INTO fleet.engine_hours_reading (machine_id, reading_hours, read_at, source, recorded_by)
    VALUES (p_machine_id, p_reading_hours, p_read_at, p_source, v_user);

    FOR v_due IN SELECT d.maintenance_plan_id AS plan_id, d.due_engine_hours AS due
                 FROM fleet.fn_maintenance_due(p_machine_id, 50) d
    LOOP
        v_so := fleet.create_service_order_draft(p_machine_id, v_due.plan_id, v_due.due);
        RETURN QUERY
            SELECT so.id, so.number, so.due_engine_hours, so.status = 'parts_reserved'
            FROM fleet.service_order so WHERE so.id = v_so;
    END LOOP;
END $$;


ALTER FUNCTION fleet.log_engine_hours(p_machine_id bigint, p_reading_hours numeric, p_read_at timestamp with time zone, p_source fleet.reading_source) OWNER TO smartspare_owner;

--
-- Name: FUNCTION log_engine_hours(p_machine_id bigint, p_reading_hours numeric, p_read_at timestamp with time zone, p_source fleet.reading_source); Type: COMMENT; Schema: fleet; Owner: smartspare_owner
--

COMMENT ON FUNCTION fleet.log_engine_hours(p_machine_id bigint, p_reading_hours numeric, p_read_at timestamp with time zone, p_source fleet.reading_source) IS 'UC02: validates and stores a reading, then drafts service orders with soft-reserved kits for every plan due within 50 h. Atomic.';


--
-- Name: trg_engine_hours_apply(); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.trg_engine_hours_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    UPDATE fleet.machine
       SET current_engine_hours = NEW.reading_hours, engine_hours_read_at = NEW.read_at
     WHERE id = NEW.machine_id;
    RETURN NULL;
END $$;


ALTER FUNCTION fleet.trg_engine_hours_apply() OWNER TO smartspare_owner;

--
-- Name: trg_engine_hours_validate(); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.trg_engine_hours_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status     fleet.machine_status;
    v_last       fleet.engine_hours_reading;
    v_elapsed_h  numeric;
BEGIN
    -- Lock the machine: concurrent readings of one machine are serialised.
    SELECT status INTO v_status FROM fleet.machine WHERE id = NEW.machine_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Machine % not found', NEW.machine_id USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_status <> 'active' THEN
        RAISE EXCEPTION 'Machine % is not active (%)', NEW.machine_id, v_status USING ERRCODE = 'SS102';
    END IF;

    SELECT * INTO v_last FROM fleet.engine_hours_reading
    WHERE machine_id = NEW.machine_id ORDER BY read_at DESC LIMIT 1;

    IF FOUND THEN
        IF NEW.read_at <= v_last.read_at THEN
            RAISE EXCEPTION 'Reading time % is not after the last reading (%)', NEW.read_at, v_last.read_at USING ERRCODE = 'SS103';
        END IF;
        IF NEW.reading_hours < v_last.reading_hours THEN
            RAISE EXCEPTION 'Entered hours (%h) cannot be less than previous recorded reading (%h)',
                  NEW.reading_hours, v_last.reading_hours USING ERRCODE = 'SS100';
        END IF;
        -- An engine cannot run more hours than wall-clock time has passed (<= 24 h per day).
        v_elapsed_h := extract(epoch FROM (NEW.read_at - v_last.read_at)) / 3600.0;
        IF NEW.reading_hours - v_last.reading_hours > v_elapsed_h THEN
            RAISE EXCEPTION 'Implausible reading: +%h engine hours within %h elapsed time',
                  NEW.reading_hours - v_last.reading_hours, round(v_elapsed_h, 1) USING ERRCODE = 'SS101';
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION fleet.trg_engine_hours_validate() OWNER TO smartspare_owner;

--
-- Name: trg_service_order_status_guard(); Type: FUNCTION; Schema: fleet; Owner: smartspare_owner
--

CREATE FUNCTION fleet.trg_service_order_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
          (OLD.status = 'draft'          AND NEW.status IN ('parts_reserved', 'in_progress', 'completed', 'cancelled'))
       OR (OLD.status = 'parts_reserved' AND NEW.status IN ('draft', 'in_progress', 'completed', 'cancelled'))
       OR (OLD.status = 'in_progress'    AND NEW.status IN ('completed', 'cancelled'))) THEN
        RAISE EXCEPTION 'Invalid service order transition % -> % (order %)', OLD.status, NEW.status, OLD.number USING ERRCODE = 'SS300';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION fleet.trg_service_order_status_guard() OWNER TO smartspare_owner;

--
-- Name: decide_recommendation(bigint, text, numeric, text); Type: FUNCTION; Schema: forecast; Owner: smartspare_owner
--

CREATE FUNCTION forecast.decide_recommendation(p_recommendation_id bigint, p_decision text, p_final_qty numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user   uuid := util.require_role('BRAND_MANAGER', 'INVENTORY_PLANNER');
    v_rec    forecast.recommendation;
    v_qty    numeric;
    v_status forecast.recommendation_status;
    v_doc    bigint;
BEGIN
    IF p_decision NOT IN ('accept', 'override', 'reject') THEN
        RAISE EXCEPTION 'Unknown decision %', p_decision USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT * INTO v_rec FROM forecast.recommendation WHERE id = p_recommendation_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Recommendation % not found', p_recommendation_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_rec.status <> 'open' THEN
        RAISE EXCEPTION 'Recommendation % is already %', p_recommendation_id, v_rec.status USING ERRCODE = 'SS300';
    END IF;
    PERFORM set_config('app.reason', coalesce(p_reason, ''), true);

    IF p_decision = 'reject' THEN
        UPDATE forecast.recommendation SET status = 'rejected', decided_by = v_user, decided_at = now(), decision_reason = p_reason
         WHERE id = p_recommendation_id;
        RETURN NULL;
    END IF;

    v_qty    := CASE WHEN p_decision = 'accept' THEN v_rec.recommended_qty ELSE p_final_qty END;
    v_status := CASE WHEN p_decision = 'accept' THEN 'accepted' ELSE 'overridden' END;

    IF v_rec.kind = 'transfer' THEN
        INSERT INTO inventory.transfer_order (from_warehouse_id, to_warehouse_id, requested_by)
        VALUES (v_rec.donor_warehouse_id, v_rec.warehouse_id, v_user) RETURNING id INTO v_doc;
        INSERT INTO inventory.transfer_order_line (transfer_order_id, part_id, quantity, proposed_qty, override_reason)
        VALUES (v_doc, v_rec.part_id, v_qty, v_rec.recommended_qty, CASE WHEN v_status = 'overridden' THEN p_reason END);
        PERFORM inventory.approve_transfer(v_doc);           -- reserves at the donor (UC01 step 11)
        UPDATE forecast.recommendation
           SET status = v_status, final_qty = v_qty, decided_by = v_user, decided_at = now(),
               decision_reason = p_reason, transfer_order_id = v_doc
         WHERE id = p_recommendation_id;
    ELSE
        -- consolidate into an open draft PO of the same supplier and hub (US13)
        SELECT id INTO v_doc FROM procurement.purchase_order
        WHERE supplier_id = v_rec.supplier_id AND warehouse_id = v_rec.warehouse_id
          AND status = 'draft' AND NOT is_urgent
        ORDER BY created_at LIMIT 1 FOR UPDATE;
        IF v_doc IS NULL THEN
            INSERT INTO procurement.purchase_order (supplier_id, warehouse_id, created_by)
            VALUES (v_rec.supplier_id, v_rec.warehouse_id, v_user) RETURNING id INTO v_doc;
        END IF;
        INSERT INTO procurement.purchase_order_line AS l (purchase_order_id, part_id, quantity, proposed_qty, override_reason)
        VALUES (v_doc, v_rec.part_id, v_qty, v_rec.recommended_qty, CASE WHEN v_status = 'overridden' THEN p_reason END)
        ON CONFLICT (purchase_order_id, part_id) DO UPDATE
            SET quantity        = l.quantity + EXCLUDED.quantity,
                proposed_qty    = coalesce(l.proposed_qty, 0) + EXCLUDED.proposed_qty,
                override_reason = coalesce(EXCLUDED.override_reason, l.override_reason);
        UPDATE forecast.recommendation
           SET status = v_status, final_qty = v_qty, decided_by = v_user, decided_at = now(),
               decision_reason = p_reason, purchase_order_id = v_doc
         WHERE id = p_recommendation_id;
    END IF;
    RETURN v_doc;
END $$;


ALTER FUNCTION forecast.decide_recommendation(p_recommendation_id bigint, p_decision text, p_final_qty numeric, p_reason text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION decide_recommendation(p_recommendation_id bigint, p_decision text, p_final_qty numeric, p_reason text); Type: COMMENT; Schema: forecast; Owner: smartspare_owner
--

COMMENT ON FUNCTION forecast.decide_recommendation(p_recommendation_id bigint, p_decision text, p_final_qty numeric, p_reason text) IS 'Accept / override (with reason) / reject a recommendation; creates and approves a transfer or adds a line to a consolidated draft PO, in one transaction.';


--
-- Name: expire_open_recommendations(interval); Type: PROCEDURE; Schema: forecast; Owner: smartspare_owner
--

CREATE PROCEDURE forecast.expire_open_recommendations(IN p_older_than interval DEFAULT '14 days'::interval)
    LANGUAGE sql
    AS $$
    UPDATE forecast.recommendation SET status = 'expired'
    WHERE status = 'open' AND created_at < now() - p_older_than;
$$;


ALTER PROCEDURE forecast.expire_open_recommendations(IN p_older_than interval) OWNER TO smartspare_owner;

--
-- Name: fn_classify_demand(numeric, numeric); Type: FUNCTION; Schema: forecast; Owner: smartspare_owner
--

CREATE FUNCTION forecast.fn_classify_demand(p_adi numeric, p_cv2 numeric) RETURNS character varying
    LANGUAGE sql STABLE
    AS $$
    SELECT dc.code FROM ref.demand_class dc
    WHERE p_adi >= dc.adi_lower AND p_adi < dc.adi_upper AND p_cv2 >= dc.cv2_lower AND p_cv2 < dc.cv2_upper
    LIMIT 1
$$;


ALTER FUNCTION forecast.fn_classify_demand(p_adi numeric, p_cv2 numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION fn_classify_demand(p_adi numeric, p_cv2 numeric); Type: COMMENT; Schema: forecast; Owner: smartspare_owner
--

COMMENT ON FUNCTION forecast.fn_classify_demand(p_adi numeric, p_cv2 numeric) IS 'Syntetos-Boylan class from ADI and CV² using the ranges in ref.demand_class.';


--
-- Name: fn_stock_position(smallint, bigint, bigint, numeric); Type: FUNCTION; Schema: forecast; Owner: smartspare_owner
--

CREATE FUNCTION forecast.fn_stock_position(p_warehouse_id smallint, p_part_id bigint, p_forecast_run_id bigint, p_lead_time_days numeric DEFAULT NULL::numeric) RETURNS TABLE(available_qty numeric, in_transit_qty numeric, base_demand_qty numeric, maintenance_demand_qty numeric, lead_time_buffer_qty numeric, safety_stock_qty numeric, net_position_qty numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH f AS (
        SELECT coalesce(sum(df.forecast_qty), 0) AS total, coalesce(avg(df.forecast_qty), 0) AS weekly
        FROM forecast.demand_forecast df
        WHERE df.forecast_run_id = p_forecast_run_id AND df.warehouse_id = p_warehouse_id AND df.part_id = p_part_id
    ), maint AS (            -- planned demand of open service orders not yet covered by a reservation
        SELECT coalesce(sum(greatest(l.qty_required - l.qty_issued - coalesce(r.held, 0), 0)), 0) AS qty
        FROM fleet.service_order_line l
        JOIN fleet.service_order s ON s.id = l.service_order_id
        LEFT JOIN LATERAL (SELECT sum(sr.quantity) AS held FROM inventory.stock_reservation sr
                           WHERE sr.service_order_line_id = l.id AND sr.status IN ('soft', 'firm')) r ON true
        WHERE s.warehouse_id = p_warehouse_id AND l.part_id = p_part_id
          AND s.status IN ('draft', 'parts_reserved', 'in_progress')
    ), lt AS (
        SELECT coalesce(p_lead_time_days,
                        (SELECT coalesce(min(sp.lead_time_days) FILTER (WHERE sp.is_preferred), min(sp.lead_time_days))
                         FROM catalog.supplier_part sp WHERE sp.part_id = p_part_id), 0) AS days
    ), pos AS (
        SELECT coalesce((SELECT b.available_qty FROM inventory.stock_balance b
                         WHERE b.warehouse_id = p_warehouse_id AND b.part_id = p_part_id), 0)            AS available,
               inventory.fn_in_transit_qty(p_warehouse_id, p_part_id)                                    AS in_transit,
               round(f.total, 3)                                                                         AS base,
               round(maint.qty, 3)                                                                       AS maintenance,
               round(f.weekly * lt.days / 7.0, 3)                                                        AS lead_time_buffer,
               coalesce((SELECT wp.safety_stock_qty FROM inventory.warehouse_part wp
                         WHERE wp.warehouse_id = p_warehouse_id AND wp.part_id = p_part_id), 0)          AS safety
        FROM f, maint, lt
    )
    SELECT available, in_transit, base, maintenance, lead_time_buffer, safety,
           available + in_transit - (base + maintenance + lead_time_buffer + safety)
    FROM pos
$$;


ALTER FUNCTION forecast.fn_stock_position(p_warehouse_id smallint, p_part_id bigint, p_forecast_run_id bigint, p_lead_time_days numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION fn_stock_position(p_warehouse_id smallint, p_part_id bigint, p_forecast_run_id bigint, p_lead_time_days numeric); Type: COMMENT; Schema: forecast; Owner: smartspare_owner
--

COMMENT ON FUNCTION forecast.fn_stock_position(p_warehouse_id smallint, p_part_id bigint, p_forecast_run_id bigint, p_lead_time_days numeric) IS 'Net = Available + InTransit - (ML forecast + unreserved maintenance demand + lead-time buffer + safety stock). Used by the recommendation engine.';


--
-- Name: promote_model(integer, numeric); Type: FUNCTION; Schema: forecast; Owner: smartspare_owner
--

CREATE FUNCTION forecast.promote_model(p_candidate_id integer, p_min_improvement numeric DEFAULT 0.10) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_cand  forecast.ml_model_version;
    v_score numeric;
    v_best  numeric;
BEGIN
    SELECT * INTO v_cand FROM forecast.ml_model_version WHERE id = p_candidate_id FOR UPDATE;
    IF NOT FOUND OR v_cand.status <> 'candidate' THEN
        RAISE EXCEPTION 'Model version % is not a candidate', p_candidate_id USING ERRCODE = 'SS300';
    END IF;

    -- series-weighted RMSSE over demand classes
    SELECT sum(rmsse * series_count) / sum(series_count) INTO v_score
    FROM forecast.benchmark_result WHERE model_version_id = p_candidate_id AND method = v_cand.algorithm;
    v_score := coalesce(v_score, v_cand.rmsse);

    SELECT min(w) INTO v_best FROM (
        SELECT sum(rmsse * series_count) / sum(series_count) AS w
        FROM forecast.benchmark_result
        WHERE model_version_id = p_candidate_id AND method <> v_cand.algorithm
        GROUP BY method) b;
    IF v_best IS NULL THEN
        RAISE EXCEPTION 'Model version % has no benchmark results', p_candidate_id USING ERRCODE = 'SS300';
    END IF;

    IF v_score <= v_best * (1 - p_min_improvement) THEN
        UPDATE forecast.ml_model_version SET status = 'retired', retired_at = now()
         WHERE status = 'active' AND coalesce(demand_class_code, '*') = coalesce(v_cand.demand_class_code, '*');
        UPDATE forecast.ml_model_version SET status = 'active', promoted_at = now() WHERE id = p_candidate_id;
        RETURN true;
    END IF;
    UPDATE forecast.ml_model_version SET status = 'rejected' WHERE id = p_candidate_id;
    RETURN false;
END $$;


ALTER FUNCTION forecast.promote_model(p_candidate_id integer, p_min_improvement numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION promote_model(p_candidate_id integer, p_min_improvement numeric); Type: COMMENT; Schema: forecast; Owner: smartspare_owner
--

COMMENT ON FUNCTION forecast.promote_model(p_candidate_id integer, p_min_improvement numeric) IS 'Promotes a candidate only if its weighted RMSSE is >= 10 % lower than the best of the 5 benchmarks; retires the previous active model atomically.';


--
-- Name: trg_model_status_guard(); Type: FUNCTION; Schema: forecast; Owner: smartspare_owner
--

CREATE FUNCTION forecast.trg_model_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NOT ((OLD.status = 'training'  AND NEW.status IN ('candidate', 'rejected'))
             OR (OLD.status = 'candidate' AND NEW.status IN ('active', 'rejected'))
             OR (OLD.status = 'active'    AND NEW.status = 'retired')) THEN
            RAISE EXCEPTION 'Invalid model transition % -> %', OLD.status, NEW.status USING ERRCODE = 'SS300';
        END IF;
        IF NEW.status IN ('active', 'retired')
           AND current_user <> (SELECT nspowner::regrole::name FROM pg_namespace WHERE nspname = 'forecast') THEN
            RAISE EXCEPTION 'Model activation is only possible through forecast.promote_model()' USING ERRCODE = 'insufficient_privilege';
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION forecast.trg_model_status_guard() OWNER TO smartspare_owner;

--
-- Name: anonymise_user(uuid); Type: FUNCTION; Schema: iam; Owner: smartspare_owner
--

CREATE FUNCTION iam.anonymise_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_admin uuid := util.require_role('ADMINISTRATOR');
    v_tag   text := left(md5(p_user_id::text), 12);
BEGIN
    IF p_user_id = v_admin THEN
        RAISE EXCEPTION 'Administrators cannot anonymise themselves' USING ERRCODE = 'SS301';
    END IF;
    PERFORM set_config('app.reason', 'GDPR Art. 17 erasure request', true);
    DELETE FROM iam.user_role  WHERE user_id = p_user_id;
    DELETE FROM iam.user_brand WHERE user_id = p_user_id;
    UPDATE iam.app_user
       SET user_name = 'anon_' || v_tag, email = 'anon-' || v_tag || '@anonymised.invalid',
           full_name = 'Anonymised User', phone = NULL, password_hash = NULL,
           is_active = false, lockout_end = NULL, last_login_at = NULL,
           security_stamp = gen_random_uuid(), anonymised_at = now()
     WHERE id = p_user_id AND anonymised_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'User % not found or already anonymised', p_user_id USING ERRCODE = 'no_data_found';
    END IF;
END $$;


ALTER FUNCTION iam.anonymise_user(p_user_id uuid) OWNER TO smartspare_owner;

--
-- Name: FUNCTION anonymise_user(p_user_id uuid); Type: COMMENT; Schema: iam; Owner: smartspare_owner
--

COMMENT ON FUNCTION iam.anonymise_user(p_user_id uuid) IS 'Irreversibly replaces personal data of a user; the row (and audit references) remain.';


--
-- Name: user_has_role(uuid, text[]); Type: FUNCTION; Schema: iam; Owner: smartspare_owner
--

CREATE FUNCTION iam.user_has_role(p_user_id uuid, VARIADIC p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM iam.user_role ur
        JOIN iam.role r     ON r.id = ur.role_id
        JOIN iam.app_user u ON u.id = ur.user_id
        WHERE ur.user_id = p_user_id AND u.is_active AND r.code = ANY (p_roles))
$$;


ALTER FUNCTION iam.user_has_role(p_user_id uuid, VARIADIC p_roles text[]) OWNER TO smartspare_owner;

--
-- Name: FUNCTION user_has_role(p_user_id uuid, VARIADIC p_roles text[]); Type: COMMENT; Schema: iam; Owner: smartspare_owner
--

COMMENT ON FUNCTION iam.user_has_role(p_user_id uuid, VARIADIC p_roles text[]) IS 'TRUE if the active user has at least one of the given role codes.';


--
-- Name: approve_transfer(bigint); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.approve_transfer(p_transfer_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user   uuid := util.require_role('BRAND_MANAGER', 'INVENTORY_PLANNER');
    v_order  inventory.transfer_order;
    v_line   record;
    v_avail  numeric;
    v_safety numeric;
BEGIN
    SELECT * INTO v_order FROM inventory.transfer_order WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer order % not found', p_transfer_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_order.status <> 'proposed' THEN
        RAISE EXCEPTION 'Transfer order % is %, only proposed orders can be approved', v_order.number, v_order.status USING ERRCODE = 'SS300';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM inventory.transfer_order_line WHERE transfer_order_id = p_transfer_id) THEN
        RAISE EXCEPTION 'Transfer order % has no lines', v_order.number USING ERRCODE = 'SS300';
    END IF;

    -- Lock balances in a deterministic order (part_id) to avoid deadlocks.
    FOR v_line IN
        SELECT l.id, l.part_id, l.quantity
        FROM inventory.transfer_order_line l
        WHERE l.transfer_order_id = p_transfer_id
        ORDER BY l.part_id
    LOOP
        SELECT b.available_qty, wp.safety_stock_qty INTO v_avail, v_safety
        FROM inventory.stock_balance b
        JOIN inventory.warehouse_part wp USING (warehouse_id, part_id)
        WHERE b.warehouse_id = v_order.from_warehouse_id AND b.part_id = v_line.part_id
        FOR UPDATE OF b;

        -- US10: a donor only gives stock above its safety buffer (urgent orders may use the buffer).
        IF NOT v_order.is_urgent AND coalesce(v_avail, 0) - v_line.quantity < coalesce(v_safety, 0) THEN
            RAISE EXCEPTION 'Donor warehouse % would fall below its safety stock for part % (available %, safety %, transfer %)',
                  v_order.from_warehouse_id, v_line.part_id, coalesce(v_avail, 0), coalesce(v_safety, 0), v_line.quantity
                  USING ERRCODE = 'SS201';
        END IF;

        INSERT INTO inventory.stock_reservation (warehouse_id, part_id, quantity, status, transfer_order_line_id, created_by)
        VALUES (v_order.from_warehouse_id, v_line.part_id, v_line.quantity, 'firm', v_line.id, v_user);
    END LOOP;

    UPDATE inventory.transfer_order
       SET status = 'approved', approved_by = v_user, approved_at = now()
     WHERE id = p_transfer_id;
END $$;


ALTER FUNCTION inventory.approve_transfer(p_transfer_id bigint) OWNER TO smartspare_owner;

--
-- Name: FUNCTION approve_transfer(p_transfer_id bigint); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.approve_transfer(p_transfer_id bigint) IS 'UC01 step 10-11: approves a proposed transfer and places firm reservations at the donor (atomic, all lines or none).';


--
-- Name: cancel_transfer(bigint, text); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.cancel_transfer(p_transfer_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user   uuid := util.require_role('BRAND_MANAGER', 'INVENTORY_PLANNER', 'ADMINISTRATOR');
    v_status inventory.transfer_status;
BEGIN
    SELECT status INTO v_status FROM inventory.transfer_order WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer order % not found', p_transfer_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_status NOT IN ('proposed', 'approved') THEN
        RAISE EXCEPTION 'A % transfer order cannot be cancelled', v_status USING ERRCODE = 'SS300';
    END IF;
    UPDATE inventory.stock_reservation r SET status = 'released'
      FROM inventory.transfer_order_line l
     WHERE l.transfer_order_id = p_transfer_id AND r.transfer_order_line_id = l.id AND r.status = 'firm';
    UPDATE inventory.transfer_order SET status = 'cancelled', cancel_reason = p_reason WHERE id = p_transfer_id;
END $$;


ALTER FUNCTION inventory.cancel_transfer(p_transfer_id bigint, p_reason text) OWNER TO smartspare_owner;

--
-- Name: dispatch_transfer(bigint); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.dispatch_transfer(p_transfer_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user   uuid := util.require_role('WAREHOUSE_KEEPER', 'ADMINISTRATOR');
    v_order  inventory.transfer_order;
    v_home   smallint;
    v_line   record;
BEGIN
    SELECT * INTO v_order FROM inventory.transfer_order WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer order % not found', p_transfer_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_order.status <> 'approved' THEN
        RAISE EXCEPTION 'Transfer order % is %, only approved orders can be dispatched', v_order.number, v_order.status USING ERRCODE = 'SS300';
    END IF;
    SELECT home_warehouse_id INTO v_home FROM iam.app_user WHERE id = v_user;
    IF v_home IS NOT NULL AND v_home <> v_order.from_warehouse_id THEN
        RAISE EXCEPTION 'Only a keeper of the donor warehouse can dispatch order %', v_order.number USING ERRCODE = 'SS302';
    END IF;

    FOR v_line IN
        SELECT l.id, l.part_id, l.quantity, p.unit_cost
        FROM inventory.transfer_order_line l JOIN catalog.part p ON p.id = l.part_id
        WHERE l.transfer_order_id = p_transfer_id ORDER BY l.part_id
    LOOP
        -- 1) release the hold, 2) post the physical issue (order matters for reserved <= on_hand)
        UPDATE inventory.stock_reservation SET status = 'consumed'
         WHERE transfer_order_line_id = v_line.id AND status = 'firm';
        INSERT INTO inventory.stock_movement (occurred_at, warehouse_id, part_id, movement_type_code, quantity,
                                              unit_cost, transfer_order_line_id, created_by)
        VALUES (now(), v_order.from_warehouse_id, v_line.part_id, 'TRANSFER_OUT', v_line.quantity,
                v_line.unit_cost, v_line.id, v_user);
    END LOOP;

    UPDATE inventory.transfer_order
       SET status = 'dispatched', dispatched_by = v_user, dispatched_at = now()
     WHERE id = p_transfer_id;
END $$;


ALTER FUNCTION inventory.dispatch_transfer(p_transfer_id bigint) OWNER TO smartspare_owner;

--
-- Name: FUNCTION dispatch_transfer(p_transfer_id bigint); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.dispatch_transfer(p_transfer_id bigint) IS 'US11: consumes the firm reservations, posts TRANSFER_OUT movements, status -> dispatched (stock is now in transit).';


--
-- Name: expire_soft_reservations(integer); Type: PROCEDURE; Schema: inventory; Owner: smartspare_owner
--

CREATE PROCEDURE inventory.expire_soft_reservations(INOUT p_expired integer DEFAULT 0)
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH expired AS (
        UPDATE inventory.stock_reservation
           SET status = 'expired'
         WHERE status = 'soft' AND expires_at < now()
        RETURNING service_order_line_id
    ), reopened AS (
        UPDATE fleet.service_order so
           SET status = 'draft'
         WHERE so.status = 'parts_reserved'
           AND so.id IN (SELECT l.service_order_id
                         FROM fleet.service_order_line l
                         JOIN expired e ON e.service_order_line_id = l.id)
        RETURNING so.id
    )
    SELECT count(*) INTO p_expired FROM expired;
END $$;


ALTER PROCEDURE inventory.expire_soft_reservations(INOUT p_expired integer) OWNER TO smartspare_owner;

--
-- Name: PROCEDURE expire_soft_reservations(INOUT p_expired integer); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON PROCEDURE inventory.expire_soft_reservations(INOUT p_expired integer) IS 'Expires overdue soft reservations and returns affected service orders to draft.';


--
-- Name: find_exceptional_demand_candidates(numeric, interval, integer); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.find_exceptional_demand_candidates(p_sigma numeric DEFAULT 3, p_lookback interval DEFAULT '2 years'::interval, p_min_events integer DEFAULT 8) RETURNS TABLE(movement_id bigint, occurred_at timestamp with time zone, warehouse_id smallint, part_id bigint, quantity numeric, mean_qty numeric, stddev_qty numeric, z_score numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH demand AS (
        SELECT m.id, m.occurred_at, m.warehouse_id, m.part_id, m.quantity,
               avg(m.quantity)         OVER w AS mean_qty,
               stddev_samp(m.quantity) OVER w AS sd,
               count(*)                OVER w AS n
        FROM inventory.stock_movement m
        JOIN ref.movement_type t ON t.code = m.movement_type_code AND t.is_demand
        WHERE m.occurred_at >= now() - p_lookback
        WINDOW w AS (PARTITION BY m.part_id)
    )
    SELECT d.id, d.occurred_at, d.warehouse_id, d.part_id, d.quantity,
           round(d.mean_qty, 3), round(d.sd, 3), round((d.quantity - d.mean_qty) / d.sd, 2)
    FROM demand d
    WHERE d.n >= p_min_events AND d.sd > 0 AND d.quantity > d.mean_qty + p_sigma * d.sd
      AND NOT EXISTS (SELECT 1 FROM inventory.demand_exception e
                      WHERE e.movement_id = d.id AND e.movement_occurred_at = d.occurred_at)
    ORDER BY 8 DESC
$$;


ALTER FUNCTION inventory.find_exceptional_demand_candidates(p_sigma numeric, p_lookback interval, p_min_events integer) OWNER TO smartspare_owner;

--
-- Name: FUNCTION find_exceptional_demand_candidates(p_sigma numeric, p_lookback interval, p_min_events integer); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.find_exceptional_demand_candidates(p_sigma numeric, p_lookback interval, p_min_events integer) IS 'US08: demand lines above mean + 3 sigma of the SKU (window functions), not yet flagged.';


--
-- Name: flag_exceptional_demand(bigint, timestamp with time zone, text, text); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.flag_exceptional_demand(p_movement_id bigint, p_occurred_at timestamp with time zone, p_reason text, p_method text DEFAULT 'manual'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('INVENTORY_PLANNER', 'BRAND_MANAGER');
BEGIN
    PERFORM set_config('app.reason', p_reason, true);
    INSERT INTO inventory.demand_exception (movement_id, movement_occurred_at, reason, detection_method, flagged_by)
    VALUES (p_movement_id, p_occurred_at, p_reason, p_method, v_user)
    ON CONFLICT (movement_id, movement_occurred_at) DO UPDATE
        SET reason = EXCLUDED.reason, flagged_by = EXCLUDED.flagged_by, flagged_at = now();
END $$;


ALTER FUNCTION inventory.flag_exceptional_demand(p_movement_id bigint, p_occurred_at timestamp with time zone, p_reason text, p_method text) OWNER TO smartspare_owner;

--
-- Name: fn_in_transit_qty(smallint, bigint); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.fn_in_transit_qty(p_warehouse_id smallint, p_part_id bigint) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT coalesce((SELECT sum(l.quantity)
                     FROM inventory.transfer_order_line l
                     JOIN inventory.transfer_order o ON o.id = l.transfer_order_id
                     WHERE o.to_warehouse_id = p_warehouse_id AND l.part_id = p_part_id
                       AND o.status = 'dispatched'), 0)
         + coalesce((SELECT sum(pl.quantity - pl.received_qty)
                     FROM procurement.purchase_order_line pl
                     JOIN procurement.purchase_order po ON po.id = pl.purchase_order_id
                     WHERE po.warehouse_id = p_warehouse_id AND pl.part_id = p_part_id
                       AND po.status IN ('approved', 'exported', 'partially_received')), 0)
$$;


ALTER FUNCTION inventory.fn_in_transit_qty(p_warehouse_id smallint, p_part_id bigint) OWNER TO smartspare_owner;

--
-- Name: FUNCTION fn_in_transit_qty(p_warehouse_id smallint, p_part_id bigint); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.fn_in_transit_qty(p_warehouse_id smallint, p_part_id bigint) IS 'Inbound quantity: dispatched transfers + not yet received approved purchase orders.';


--
-- Name: receive_transfer(bigint); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.receive_transfer(p_transfer_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user   uuid := util.require_role('WAREHOUSE_KEEPER', 'ADMINISTRATOR');
    v_order  inventory.transfer_order;
    v_home   smallint;
BEGIN
    SELECT * INTO v_order FROM inventory.transfer_order WHERE id = p_transfer_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transfer order % not found', p_transfer_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_order.status <> 'dispatched' THEN
        RAISE EXCEPTION 'Transfer order % is %, only dispatched orders can be received', v_order.number, v_order.status USING ERRCODE = 'SS300';
    END IF;
    SELECT home_warehouse_id INTO v_home FROM iam.app_user WHERE id = v_user;
    IF v_home IS NOT NULL AND v_home <> v_order.to_warehouse_id THEN
        RAISE EXCEPTION 'Only a keeper of the recipient warehouse can receive order %', v_order.number USING ERRCODE = 'SS302';
    END IF;

    INSERT INTO inventory.stock_movement (occurred_at, warehouse_id, part_id, movement_type_code, quantity,
                                          unit_cost, transfer_order_line_id, created_by)
    SELECT greatest(now(), v_order.dispatched_at), v_order.to_warehouse_id, l.part_id, 'TRANSFER_IN', l.quantity,
           p.unit_cost, l.id, v_user
    FROM inventory.transfer_order_line l JOIN catalog.part p ON p.id = l.part_id
    WHERE l.transfer_order_id = p_transfer_id
    ORDER BY l.part_id;

    UPDATE inventory.transfer_order
       SET status = 'received', received_by = v_user, received_at = greatest(now(), v_order.dispatched_at)
     WHERE id = p_transfer_id;
END $$;


ALTER FUNCTION inventory.receive_transfer(p_transfer_id bigint) OWNER TO smartspare_owner;

--
-- Name: FUNCTION receive_transfer(p_transfer_id bigint); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.receive_transfer(p_transfer_id bigint) IS 'US11: posts TRANSFER_IN movements at the recipient hub, status -> received.';


--
-- Name: trg_demand_exception_validate(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_demand_exception_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1
                   FROM inventory.stock_movement m
                   JOIN ref.movement_type t ON t.code = m.movement_type_code
                   WHERE m.id = NEW.movement_id AND m.occurred_at = NEW.movement_occurred_at AND t.is_demand) THEN
        RAISE EXCEPTION 'Movement % is not a demand movement and cannot be flagged as exceptional', NEW.movement_id
              USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION inventory.trg_demand_exception_validate() OWNER TO smartspare_owner;

--
-- Name: trg_stock_movement_apply(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_stock_movement_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_sign       smallint;
    v_available  numeric;
BEGIN
    SELECT mt.balance_sign INTO STRICT v_sign
    FROM ref.movement_type mt WHERE mt.code = NEW.movement_type_code;

    IF v_sign = 0 THEN
        RETURN NULL;                         -- imported history: no physical effect
    END IF;

    IF v_sign < 0 THEN
        -- Row lock serialises concurrent issues of the same SKU at the same hub.
        SELECT b.available_qty INTO v_available
        FROM inventory.stock_balance b
        WHERE b.warehouse_id = NEW.warehouse_id AND b.part_id = NEW.part_id
        FOR UPDATE;
        IF coalesce(v_available, 0) < NEW.quantity THEN
            RAISE EXCEPTION 'Insufficient stock of part % in warehouse %: available %, requested % (%)',
                  NEW.part_id, NEW.warehouse_id, coalesce(v_available, 0), NEW.quantity, NEW.movement_type_code
                  USING ERRCODE = 'SS200',
                        HINT = 'Reserved stock must be consumed through its reservation.';
        END IF;
    END IF;

    IF v_sign < 0 THEN
        -- The row exists and is locked (checked above). Plain UPDATE: an upsert would
        -- evaluate the CHECK constraints on the negative *proposed* row first.
        UPDATE inventory.stock_balance b
           SET on_hand_qty      = b.on_hand_qty - NEW.quantity,
               last_movement_at = greatest(b.last_movement_at, NEW.occurred_at),
               updated_at       = now()
         WHERE b.warehouse_id = NEW.warehouse_id AND b.part_id = NEW.part_id;
    ELSE
        INSERT INTO inventory.warehouse_part (warehouse_id, part_id)
        VALUES (NEW.warehouse_id, NEW.part_id)
        ON CONFLICT DO NOTHING;

        INSERT INTO inventory.stock_balance AS b (warehouse_id, part_id, on_hand_qty, last_movement_at)
        VALUES (NEW.warehouse_id, NEW.part_id, NEW.quantity, NEW.occurred_at)
        ON CONFLICT (warehouse_id, part_id) DO UPDATE
            SET on_hand_qty      = b.on_hand_qty + EXCLUDED.on_hand_qty,
                last_movement_at = greatest(b.last_movement_at, EXCLUDED.last_movement_at),
                updated_at       = now();
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION inventory.trg_stock_movement_apply() OWNER TO smartspare_owner;

--
-- Name: FUNCTION trg_stock_movement_apply(); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.trg_stock_movement_apply() IS 'AFTER INSERT on the ledger: applies +/- quantity to stock_balance with a row lock; rejects issues exceeding available stock (SS200).';


--
-- Name: trg_stock_reservation_guard(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_stock_reservation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status NOT IN ('soft', 'firm') THEN
            RAISE EXCEPTION 'A reservation must be created as soft or firm, not %', NEW.status USING ERRCODE = 'SS300';
        END IF;
        RETURN NEW;
    END IF;

    IF (NEW.warehouse_id, NEW.part_id) IS DISTINCT FROM (OLD.warehouse_id, OLD.part_id)
       OR NEW.service_order_line_id  IS DISTINCT FROM OLD.service_order_line_id
       OR NEW.transfer_order_line_id IS DISTINCT FROM OLD.transfer_order_line_id THEN
        RAISE EXCEPTION 'Location and source document of reservation % cannot be changed', OLD.id USING ERRCODE = 'SS300';
    END IF;

    IF OLD.status NOT IN ('soft', 'firm')
       AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.quantity IS DISTINCT FROM OLD.quantity) THEN
        RAISE EXCEPTION 'Reservation % is already closed (%)', OLD.id, OLD.status USING ERRCODE = 'SS300';
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NOT ((OLD.status = 'soft' AND NEW.status IN ('firm', 'consumed', 'released', 'expired'))
             OR (OLD.status = 'firm' AND NEW.status IN ('consumed', 'released'))) THEN
            RAISE EXCEPTION 'Invalid reservation transition % -> %', OLD.status, NEW.status USING ERRCODE = 'SS300';
        END IF;
        IF NEW.status IN ('consumed', 'released', 'expired') THEN
            NEW.closed_at := now();
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION inventory.trg_stock_reservation_guard() OWNER TO smartspare_owner;

--
-- Name: trg_stock_reservation_sync(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_stock_reservation_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_delta      numeric := 0;
    v_wh         smallint := coalesce(NEW.warehouse_id, OLD.warehouse_id);
    v_part       bigint   := coalesce(NEW.part_id, OLD.part_id);
    v_available  numeric;
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.status IN ('soft', 'firm') THEN v_delta := v_delta - OLD.quantity; END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.status IN ('soft', 'firm') THEN v_delta := v_delta + NEW.quantity; END IF;
    IF v_delta = 0 THEN RETURN NULL; END IF;

    SELECT b.available_qty INTO v_available
    FROM inventory.stock_balance b
    WHERE b.warehouse_id = v_wh AND b.part_id = v_part
    FOR UPDATE;

    IF v_delta > 0 AND coalesce(v_available, 0) < v_delta THEN
        RAISE EXCEPTION 'Insufficient available stock of part % in warehouse %: available %, to reserve %',
              v_part, v_wh, coalesce(v_available, 0), v_delta USING ERRCODE = 'SS200';
    END IF;

    UPDATE inventory.stock_balance
       SET reserved_qty = reserved_qty + v_delta, updated_at = now()
     WHERE warehouse_id = v_wh AND part_id = v_part;
    RETURN NULL;
END $$;


ALTER FUNCTION inventory.trg_stock_reservation_sync() OWNER TO smartspare_owner;

--
-- Name: FUNCTION trg_stock_reservation_sync(); Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON FUNCTION inventory.trg_stock_reservation_sync() IS 'Keeps stock_balance.reserved_qty equal to the sum of active (soft/firm) reservations.';


--
-- Name: trg_transfer_line_editable(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_transfer_line_editable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status inventory.transfer_status;
BEGIN
    SELECT status INTO v_status FROM inventory.transfer_order
    WHERE id = coalesce(NEW.transfer_order_id, OLD.transfer_order_id);
    IF v_status IS DISTINCT FROM 'proposed' THEN
        RAISE EXCEPTION 'Lines of a % transfer order cannot be changed', v_status USING ERRCODE = 'SS300';
    END IF;
    RETURN coalesce(NEW, OLD);
END $$;


ALTER FUNCTION inventory.trg_transfer_line_editable() OWNER TO smartspare_owner;

--
-- Name: trg_transfer_order_status_guard(); Type: FUNCTION; Schema: inventory; Owner: smartspare_owner
--

CREATE FUNCTION inventory.trg_transfer_order_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
          (OLD.status = 'proposed'   AND NEW.status IN ('approved', 'cancelled'))
       OR (OLD.status = 'approved'   AND NEW.status IN ('dispatched', 'cancelled'))
       OR (OLD.status = 'dispatched' AND NEW.status = 'received')) THEN
        RAISE EXCEPTION 'Invalid transfer order transition % -> % (order %)', OLD.status, NEW.status, OLD.number
              USING ERRCODE = 'SS300';
    END IF;
    IF OLD.status <> 'proposed' AND (NEW.from_warehouse_id, NEW.to_warehouse_id) IS DISTINCT FROM (OLD.from_warehouse_id, OLD.to_warehouse_id) THEN
        RAISE EXCEPTION 'Route of transfer order % cannot change after approval', OLD.number USING ERRCODE = 'SS300';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION inventory.trg_transfer_order_status_guard() OWNER TO smartspare_owner;

--
-- Name: refresh_all(); Type: PROCEDURE; Schema: mart; Owner: smartspare_owner
--

CREATE PROCEDURE mart.refresh_all()
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_view text;
    v_t0   timestamptz;
    v_rows bigint;
BEGIN
    FOREACH v_view IN ARRAY ARRAY['mart.mv_weekly_demand', 'mart.mv_demand_profile'] LOOP   -- dependency order
        v_t0 := clock_timestamp();
        BEGIN
            IF (SELECT ispopulated FROM pg_matviews WHERE schemaname || '.' || matviewname = v_view) THEN
                EXECUTE 'REFRESH MATERIALIZED VIEW CONCURRENTLY ' || v_view;
            ELSE
                EXECUTE 'REFRESH MATERIALIZED VIEW ' || v_view;
            END IF;
            EXECUTE 'SELECT count(*) FROM ' || v_view INTO v_rows;
            INSERT INTO mart.refresh_log (view_name, started_at, finished_at, row_count, status)
            VALUES (v_view, v_t0, clock_timestamp(), v_rows, 'ok');
        EXCEPTION WHEN others THEN
            INSERT INTO mart.refresh_log (view_name, started_at, finished_at, status, message)
            VALUES (v_view, v_t0, clock_timestamp(), 'failed', SQLERRM);
            RAISE WARNING 'Refresh of % failed: %', v_view, SQLERRM;
            RETURN;                                    -- dependent views are not refreshed
        END;
    END LOOP;
END $$;


ALTER PROCEDURE mart.refresh_all() OWNER TO smartspare_owner;

--
-- Name: PROCEDURE refresh_all(); Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON PROCEDURE mart.refresh_all() IS 'Refreshes the data marts (concurrently once populated) and logs duration/rows/failures. Nightly Quartz.NET job and after imports.';


--
-- Name: approve_purchase_order(bigint); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.approve_purchase_order(p_po_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('BRAND_MANAGER', 'SPONSOR');
    v_po   procurement.purchase_order;
    v_lead integer;
BEGIN
    SELECT * INTO v_po FROM procurement.purchase_order WHERE id = p_po_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order % not found', p_po_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_po.status <> 'pending_approval' THEN
        RAISE EXCEPTION 'Purchase order % is %, expected pending_approval', v_po.number, v_po.status USING ERRCODE = 'SS300';
    END IF;
    IF v_po.total_amount > 5000 AND v_po.created_by = v_user THEN
        RAISE EXCEPTION 'Four-eyes rule: % (EUR %) must be approved by another manager', v_po.number, v_po.total_amount USING ERRCODE = 'SS301';
    END IF;

    SELECT max(sp.lead_time_days) INTO v_lead
    FROM procurement.purchase_order_line l
    JOIN catalog.supplier_part sp ON sp.part_id = l.part_id AND sp.supplier_id = v_po.supplier_id
    WHERE l.purchase_order_id = p_po_id;

    UPDATE procurement.purchase_order
       SET status = 'approved', approved_by = v_user, approved_at = now(),
           expected_arrival_date = current_date + coalesce(v_lead, 0)
     WHERE id = p_po_id;
END $$;


ALTER FUNCTION procurement.approve_purchase_order(p_po_id bigint) OWNER TO smartspare_owner;

--
-- Name: FUNCTION approve_purchase_order(p_po_id bigint); Type: COMMENT; Schema: procurement; Owner: smartspare_owner
--

COMMENT ON FUNCTION procurement.approve_purchase_order(p_po_id bigint) IS 'US14: approves a submitted PO; > EUR 5,000 requires an approver other than the author (also a CHECK constraint).';


--
-- Name: cancel_purchase_order(bigint, text); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.cancel_purchase_order(p_po_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('BRAND_MANAGER', 'SPONSOR', 'ADMINISTRATOR');
BEGIN
    IF EXISTS (SELECT 1 FROM procurement.purchase_order_line WHERE purchase_order_id = p_po_id AND received_qty > 0) THEN
        RAISE EXCEPTION 'Purchase order % already has receipts and cannot be cancelled', p_po_id USING ERRCODE = 'SS300';
    END IF;
    PERFORM set_config('app.reason', p_reason, true);
    UPDATE procurement.purchase_order SET status = 'cancelled', cancel_reason = p_reason WHERE id = p_po_id;
END $$;


ALTER FUNCTION procurement.cancel_purchase_order(p_po_id bigint, p_reason text) OWNER TO smartspare_owner;

