--
-- Name: receive_purchase_order_line(bigint, numeric); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.receive_purchase_order_line(p_line_id bigint, p_quantity numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('WAREHOUSE_KEEPER', 'ADMINISTRATOR');
    v_line procurement.purchase_order_line;
    v_po   procurement.purchase_order;
BEGIN
    SELECT * INTO v_line FROM procurement.purchase_order_line WHERE id = p_line_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'PO line % not found', p_line_id USING ERRCODE = 'no_data_found'; END IF;
    SELECT * INTO v_po FROM procurement.purchase_order WHERE id = v_line.purchase_order_id FOR UPDATE;
    IF v_po.status NOT IN ('approved', 'exported', 'partially_received') THEN
        RAISE EXCEPTION 'Purchase order % is % and cannot be received', v_po.number, v_po.status USING ERRCODE = 'SS300';
    END IF;
    IF p_quantity <= 0 OR v_line.received_qty + p_quantity > v_line.quantity THEN
        RAISE EXCEPTION 'Receipt of % exceeds the open quantity % of line %', p_quantity, v_line.quantity - v_line.received_qty, p_line_id
              USING ERRCODE = 'check_violation';
    END IF;

    INSERT INTO inventory.stock_movement (occurred_at, warehouse_id, part_id, movement_type_code, quantity,
                                          unit_cost, purchase_order_line_id, created_by)
    VALUES (now(), v_po.warehouse_id, v_line.part_id, 'RECEIPT_PO', p_quantity, v_line.unit_price, p_line_id, v_user);
    UPDATE procurement.purchase_order_line SET received_qty = received_qty + p_quantity WHERE id = p_line_id;

    UPDATE procurement.purchase_order
       SET status = CASE WHEN EXISTS (SELECT 1 FROM procurement.purchase_order_line
                                      WHERE purchase_order_id = v_po.id AND received_qty < quantity)
                         THEN 'partially_received'::procurement.po_status
                         ELSE 'received'::procurement.po_status END
     WHERE id = v_po.id;
END $$;


ALTER FUNCTION procurement.receive_purchase_order_line(p_line_id bigint, p_quantity numeric) OWNER TO smartspare_owner;

--
-- Name: submit_purchase_order(bigint); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.submit_purchase_order(p_po_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := util.require_role('BRAND_MANAGER', 'INVENTORY_PLANNER');
BEGIN
    PERFORM 1 FROM procurement.purchase_order WHERE id = p_po_id FOR UPDATE;
    IF NOT EXISTS (SELECT 1 FROM procurement.purchase_order_line WHERE purchase_order_id = p_po_id) THEN
        RAISE EXCEPTION 'Purchase order % has no lines', p_po_id USING ERRCODE = 'SS300';
    END IF;
    UPDATE procurement.purchase_order SET status = 'pending_approval', submitted_at = now() WHERE id = p_po_id;
END $$;


ALTER FUNCTION procurement.submit_purchase_order(p_po_id bigint) OWNER TO smartspare_owner;

--
-- Name: trg_po_line_total(); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.trg_po_line_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_po bigint := coalesce(NEW.purchase_order_id, OLD.purchase_order_id);
BEGIN
    UPDATE procurement.purchase_order po
       SET total_amount = (SELECT coalesce(sum(l.line_amount), 0)
                           FROM procurement.purchase_order_line l WHERE l.purchase_order_id = v_po)
     WHERE po.id = v_po;
    RETURN NULL;
END $$;


ALTER FUNCTION procurement.trg_po_line_total() OWNER TO smartspare_owner;

--
-- Name: trg_po_line_validate(); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.trg_po_line_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_po    procurement.purchase_order;
    v_sp    catalog.supplier_part;
    v_price numeric;
BEGIN
    SELECT * INTO v_po FROM procurement.purchase_order
    WHERE id = coalesce(NEW.purchase_order_id, OLD.purchase_order_id);

    IF v_po.status NOT IN ('draft', 'pending_approval') THEN
        RAISE EXCEPTION 'Lines of purchase order % (%) cannot be changed', v_po.number, v_po.status USING ERRCODE = 'SS300';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;

    SELECT * INTO v_sp FROM catalog.supplier_part WHERE supplier_id = v_po.supplier_id AND part_id = NEW.part_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Part % is not offered by supplier %', NEW.part_id, v_po.supplier_id USING ERRCODE = 'SS401';
    END IF;
    IF NEW.quantity < v_sp.moq OR mod(NEW.quantity, v_sp.pack_size) <> 0 THEN
        RAISE EXCEPTION 'Quantity % violates supplier conditions (MOQ %, pack size %)', NEW.quantity, v_sp.moq, v_sp.pack_size
              USING ERRCODE = 'SS400',
                    HINT = format('Nearest valid quantity: %s', ceil(greatest(NEW.quantity, v_sp.moq) / v_sp.pack_size) * v_sp.pack_size);
    END IF;
    IF NEW.unit_price IS NULL THEN   -- default price from the price list valid today
        SELECT sp.unit_price INTO v_price FROM catalog.supplier_price sp
        WHERE sp.supplier_part_id = v_sp.id AND sp.valid_during @> current_date;
        IF v_price IS NULL THEN
            RAISE EXCEPTION 'No valid price of supplier % for part % on %', v_po.supplier_id, NEW.part_id, current_date USING ERRCODE = 'SS402';
        END IF;
        NEW.unit_price := v_price;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION procurement.trg_po_line_validate() OWNER TO smartspare_owner;

--
-- Name: trg_po_status_guard(); Type: FUNCTION; Schema: procurement; Owner: smartspare_owner
--

CREATE FUNCTION procurement.trg_po_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
          (OLD.status = 'draft'              AND NEW.status IN ('pending_approval', 'cancelled'))
       OR (OLD.status = 'pending_approval'   AND NEW.status IN ('approved', 'draft', 'cancelled'))
       OR (OLD.status = 'approved'           AND NEW.status IN ('exported', 'partially_received', 'received', 'cancelled'))
       OR (OLD.status = 'exported'           AND NEW.status IN ('partially_received', 'received', 'cancelled'))
       OR (OLD.status = 'partially_received' AND NEW.status = 'received')) THEN
        RAISE EXCEPTION 'Invalid purchase order transition % -> % (order %)', OLD.status, NEW.status, OLD.number USING ERRCODE = 'SS300';
    END IF;
    IF OLD.status NOT IN ('draft', 'pending_approval') AND NEW.supplier_id IS DISTINCT FROM OLD.supplier_id THEN
        RAISE EXCEPTION 'Supplier of an approved purchase order cannot change' USING ERRCODE = 'SS300';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION procurement.trg_po_status_guard() OWNER TO smartspare_owner;

--
-- Name: load_demand_history(bigint); Type: FUNCTION; Schema: staging; Owner: smartspare_owner
--

CREATE FUNCTION staging.load_demand_history(p_batch_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows integer;
BEGIN
    INSERT INTO inventory.stock_movement (occurred_at, warehouse_id, part_id, movement_type_code, quantity,
                                          import_batch_id, external_doc_ref)
    SELECT s.occurred_at, s.warehouse_id, s.part_id, 'HISTORICAL_DEMAND', s.quantity, p_batch_id, s.doc_ref
    FROM staging.demand_history s
    WHERE s.import_batch_id = p_batch_id AND s.is_valid AND NOT s.is_duplicate
    ORDER BY s.occurred_at;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows;
END $$;


ALTER FUNCTION staging.load_demand_history(p_batch_id bigint) OWNER TO smartspare_owner;

--
-- Name: load_part_catalog(bigint); Type: FUNCTION; Schema: staging; Owner: smartspare_owner
--

CREATE FUNCTION staging.load_part_catalog(p_batch_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows integer;
BEGIN
    -- Upsert by natural key; only rows whose values actually change are updated.
    INSERT INTO catalog.part AS p (brand_id, oem_part_number, description, category_id, uom_id, weight_kg, unit_cost, is_condition_based)
    SELECT s.brand_id, s.oem_part_number, s.description, s.category_id, s.uom_id, s.weight_kg, s.unit_cost, s.is_condition_based
    FROM staging.part_catalog s
    WHERE s.import_batch_id = p_batch_id AND s.is_valid
    ON CONFLICT (brand_id, oem_part_number) DO UPDATE
        SET description = EXCLUDED.description, category_id = EXCLUDED.category_id, uom_id = EXCLUDED.uom_id,
            weight_kg = EXCLUDED.weight_kg, unit_cost = EXCLUDED.unit_cost, is_condition_based = EXCLUDED.is_condition_based
        WHERE (p.description, p.category_id, p.uom_id, p.weight_kg, p.unit_cost, p.is_condition_based)
              IS DISTINCT FROM
              (EXCLUDED.description, EXCLUDED.category_id, EXCLUDED.uom_id, EXCLUDED.weight_kg, EXCLUDED.unit_cost, EXCLUDED.is_condition_based);
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows;
END $$;


ALTER FUNCTION staging.load_part_catalog(p_batch_id bigint) OWNER TO smartspare_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: import_batch; Type: TABLE; Schema: raw; Owner: smartspare_owner
--

CREATE TABLE raw.import_batch (
    id bigint NOT NULL,
    source raw.import_source NOT NULL,
    file_name character varying(255) NOT NULL,
    file_sha256 character(64) NOT NULL,
    status raw.import_status DEFAULT 'uploaded'::raw.import_status NOT NULL,
    total_rows integer DEFAULT 0 NOT NULL,
    valid_rows integer,
    error_rows integer,
    loaded_rows integer,
    uploaded_by uuid,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    message text,
    CONSTRAINT ck_import_batch_counts CHECK (((total_rows >= 0) AND ((COALESCE(valid_rows, 0) + COALESCE(error_rows, 0)) <= total_rows) AND (COALESCE(loaded_rows, 0) <= COALESCE(valid_rows, total_rows)))),
    CONSTRAINT ck_import_batch_processed CHECK (((status = 'uploaded'::raw.import_status) OR (processed_at IS NOT NULL))),
    CONSTRAINT ck_import_batch_sha CHECK ((file_sha256 ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE raw.import_batch OWNER TO smartspare_owner;

--
-- Name: TABLE import_batch; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON TABLE raw.import_batch IS 'One uploaded CSV file: source, SHA-256 (duplicate-file protection), processing status and row counts (load monitoring).';


--
-- Name: COLUMN import_batch.id; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.id IS 'Surrogate primary key.';


--
-- Name: COLUMN import_batch.file_sha256; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.file_sha256 IS 'SHA-256 of the file content; the same file cannot be imported twice.';


--
-- Name: COLUMN import_batch.status; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.status IS 'Workflow status (state machine guarded by trigger).';


--
-- Name: COLUMN import_batch.uploaded_by; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.uploaded_by IS 'User who created the record (iam.app_user).';


--
-- Name: COLUMN import_batch.uploaded_at; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.uploaded_at IS 'Time of the uploaded event.';


--
-- Name: COLUMN import_batch.processed_at; Type: COMMENT; Schema: raw; Owner: smartspare_owner
--

COMMENT ON COLUMN raw.import_batch.processed_at IS 'Time of the processed event.';


--
-- Name: process_batch(bigint, numeric); Type: FUNCTION; Schema: staging; Owner: smartspare_owner
--

CREATE FUNCTION staging.process_batch(p_batch_id bigint, p_max_error_ratio numeric DEFAULT 0.05) RETURNS raw.import_batch
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    v_batch   raw.import_batch;
    v_total   integer;
    v_errors  integer;
    v_dups    integer := 0;
    v_loaded  integer := 0;
BEGIN
    SELECT * INTO v_batch FROM raw.import_batch WHERE id = p_batch_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Import batch % not found', p_batch_id USING ERRCODE = 'no_data_found'; END IF;
    IF v_batch.status NOT IN ('uploaded', 'failed') THEN
        RAISE EXCEPTION 'Import batch % is already %', p_batch_id, v_batch.status USING ERRCODE = 'SS300';
    END IF;

    IF v_batch.source = 'part_catalog' THEN
        SELECT count(*) INTO v_total FROM raw.part_catalog_row WHERE import_batch_id = p_batch_id;
        v_errors := staging.validate_part_catalog(p_batch_id);
    ELSE
        SELECT count(*) INTO v_total FROM raw.demand_history_row WHERE import_batch_id = p_batch_id;
        v_errors := staging.validate_demand_history(p_batch_id);
        SELECT count(*) INTO v_dups FROM staging.demand_history WHERE import_batch_id = p_batch_id AND is_duplicate;
    END IF;

    IF v_total = 0 OR v_errors::numeric / v_total > p_max_error_ratio THEN
        UPDATE raw.import_batch
           SET status = 'failed', total_rows = v_total, valid_rows = v_total - v_errors, error_rows = v_errors,
               loaded_rows = 0, processed_at = now(),
               message = CASE WHEN v_total = 0 THEN 'Empty file'
                              ELSE format('%s of %s rows invalid (%s%%) > threshold %s%%: nothing loaded',
                                          v_errors, v_total, round(100.0 * v_errors / v_total, 1), round(100 * p_max_error_ratio, 1)) END
         WHERE id = p_batch_id
        RETURNING * INTO v_batch;
        RETURN v_batch;
    END IF;

    v_loaded := CASE v_batch.source WHEN 'part_catalog' THEN staging.load_part_catalog(p_batch_id)
                                    ELSE staging.load_demand_history(p_batch_id) END;

    UPDATE raw.import_batch
       SET status = 'loaded', total_rows = v_total, valid_rows = v_total - v_errors, error_rows = v_errors,
           loaded_rows = v_loaded, processed_at = now(),
           message = format('%s rows: %s loaded/updated, %s invalid, %s duplicates skipped', v_total, v_loaded, v_errors, v_dups)
     WHERE id = p_batch_id
    RETURNING * INTO v_batch;
    RETURN v_batch;
END $$;


ALTER FUNCTION staging.process_batch(p_batch_id bigint, p_max_error_ratio numeric) OWNER TO smartspare_owner;

--
-- Name: FUNCTION process_batch(p_batch_id bigint, p_max_error_ratio numeric); Type: COMMENT; Schema: staging; Owner: smartspare_owner
--

COMMENT ON FUNCTION staging.process_batch(p_batch_id bigint, p_max_error_ratio numeric) IS 'Validates a raw batch into staging and loads core tables if the share of invalid rows <= threshold (default 5 %). Returns the load report.';


--
-- Name: validate_demand_history(bigint); Type: FUNCTION; Schema: staging; Owner: smartspare_owner
--

CREATE FUNCTION staging.validate_demand_history(p_batch_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_errors integer;
BEGIN
    DELETE FROM staging.import_error   WHERE import_batch_id = p_batch_id;
    DELETE FROM staging.demand_history WHERE import_batch_id = p_batch_id;

    DROP TABLE IF EXISTS tmp_dh;
    CREATE TEMP TABLE tmp_dh ON COMMIT DROP AS
    SELECT r.import_batch_id, r.line_no,
           util.try_date(r.doc_date)         AS doc_date,
           w.id                              AS warehouse_id,
           p.id                              AS part_id,
           util.try_numeric(r.quantity)      AS quantity,
           left(nullif(btrim(r.doc_ref), ''), 40) AS doc_ref,
           r.doc_date AS date_raw, r.warehouse_code, r.brand_code, r.oem_part_number, r.quantity AS qty_raw
    FROM raw.demand_history_row r
    LEFT JOIN inventory.warehouse w ON w.code = upper(btrim(r.warehouse_code))
    LEFT JOIN ref.brand b           ON b.code = upper(btrim(r.brand_code))
    LEFT JOIN catalog.part p        ON p.brand_id = b.id
                                   AND p.oem_part_number = upper(regexp_replace(btrim(r.oem_part_number), '\s+', '', 'g'))
    WHERE r.import_batch_id = p_batch_id;
    ANALYZE tmp_dh;

    INSERT INTO staging.import_error (import_batch_id, line_no, column_name, error_code, message)
    SELECT t.import_batch_id, t.line_no, e.col, e.code, e.msg
    FROM tmp_dh t
    CROSS JOIN LATERAL (VALUES
        ('doc_date', CASE WHEN t.doc_date IS NULL THEN 'FORMAT'
                          WHEN t.doc_date > current_date OR t.doc_date < DATE '2000-01-01' THEN 'RANGE' END,
                     format('Invalid date "%s" (expected YYYY-MM-DD, not in the future)', t.date_raw)),
        ('warehouse_code', CASE WHEN t.warehouse_id IS NULL THEN 'UNKNOWN_REF' END,
                     format('Unknown warehouse "%s"', t.warehouse_code)),
        ('oem_part_number', CASE WHEN t.part_id IS NULL THEN 'UNKNOWN_REF' END,
                     format('Unknown part %s/%s (import the catalogue first)', t.brand_code, t.oem_part_number)),
        ('quantity', CASE WHEN t.quantity IS NULL THEN 'TYPE' WHEN t.quantity <= 0 OR t.quantity > 999999 THEN 'RANGE' END,
                     format('Invalid quantity "%s"', t.qty_raw))
    ) AS e(col, code, msg)
    WHERE e.code IS NOT NULL;

    INSERT INTO staging.demand_history (import_batch_id, line_no, occurred_at, warehouse_id, part_id, quantity, doc_ref, row_hash, is_valid)
    SELECT t.import_batch_id, t.line_no,
           (t.doc_date + time '12:00') AT TIME ZONE 'Europe/Vilnius',
           t.warehouse_id, t.part_id,
           CASE WHEN t.quantity > 0 AND t.quantity <= 999999 THEN round(t.quantity, 3) END,   -- out-of-range stays NULL (error logged)
           t.doc_ref,
           CASE WHEN t.doc_date IS NOT NULL AND t.warehouse_id IS NOT NULL AND t.part_id IS NOT NULL
                     AND t.quantity > 0 AND t.quantity <= 999999
                THEN public.digest(concat_ws('|', t.doc_date, t.warehouse_id, t.part_id, coalesce(t.doc_ref, ''), round(t.quantity, 3)), 'sha256') END,
           NOT EXISTS (SELECT 1 FROM staging.import_error e WHERE e.import_batch_id = t.import_batch_id AND e.line_no = t.line_no)
    FROM tmp_dh t;

    ANALYZE staging.demand_history;

    -- Deduplication: within the file (window function, first line wins) and
    -- against batches loaded earlier (partial index ix_staging_demand_history_hash).
    UPDATE staging.demand_history d SET is_duplicate = true
    FROM (
        SELECT x.line_no
        FROM (SELECT s.line_no, row_number() OVER (PARTITION BY s.row_hash ORDER BY s.line_no) AS rn
              FROM staging.demand_history s
              WHERE s.import_batch_id = p_batch_id AND s.is_valid) x
        WHERE x.rn > 1
        UNION
        SELECT s.line_no
        FROM staging.demand_history s
        WHERE s.import_batch_id = p_batch_id AND s.is_valid
          AND EXISTS (SELECT 1 FROM staging.demand_history d2
                      JOIN raw.import_batch b2 ON b2.id = d2.import_batch_id AND b2.status = 'loaded'
                      WHERE d2.row_hash = s.row_hash AND d2.is_valid AND NOT d2.is_duplicate)
    ) dup
    WHERE d.import_batch_id = p_batch_id AND d.line_no = dup.line_no;

    INSERT INTO staging.import_error (import_batch_id, line_no, column_name, error_code, message)
    SELECT import_batch_id, line_no, 'row', 'DUPLICATE', 'Record already imported (same date, hub, part, document, quantity)'
    FROM staging.demand_history WHERE import_batch_id = p_batch_id AND is_duplicate;

    SELECT count(DISTINCT line_no) INTO v_errors FROM staging.import_error
    WHERE import_batch_id = p_batch_id AND error_code <> 'DUPLICATE';
    RETURN v_errors;
END $$;


ALTER FUNCTION staging.validate_demand_history(p_batch_id bigint) OWNER TO smartspare_owner;

--
-- Name: validate_part_catalog(bigint); Type: FUNCTION; Schema: staging; Owner: smartspare_owner
--

CREATE FUNCTION staging.validate_part_catalog(p_batch_id bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_errors integer;
BEGIN
    DELETE FROM staging.import_error WHERE import_batch_id = p_batch_id;
    DELETE FROM staging.part_catalog WHERE import_batch_id = p_batch_id;

    -- typed + normalised projection of the raw rows
    DROP TABLE IF EXISTS tmp_pc;
    CREATE TEMP TABLE tmp_pc ON COMMIT DROP AS
    SELECT r.import_batch_id, r.line_no,
           b.id                                                    AS brand_id,
           upper(regexp_replace(btrim(r.oem_part_number), '\s+', '', 'g')) AS oem,
           left(regexp_replace(btrim(r.description), '\s+', ' ', 'g'), 300) AS description,
           c.id                                                    AS category_id,
           u.id                                                    AS uom_id,
           util.try_numeric(r.weight_kg)                           AS weight_kg,
           util.try_numeric(r.unit_cost)                           AS unit_cost,
           lower(btrim(coalesce(r.condition_based, ''))) IN ('1', 'true', 'yes', 'y') AS condition_based,
           r.brand_code, r.category_code, r.uom_code, r.weight_kg AS weight_raw, r.unit_cost AS cost_raw
    FROM raw.part_catalog_row r
    LEFT JOIN ref.brand b            ON b.code = upper(btrim(r.brand_code))
    LEFT JOIN ref.part_category c    ON c.code = upper(btrim(r.category_code))
    LEFT JOIN ref.unit_of_measure u  ON u.code = upper(btrim(r.uom_code))
    WHERE r.import_batch_id = p_batch_id;
    ANALYZE tmp_pc;

    INSERT INTO staging.import_error (import_batch_id, line_no, column_name, error_code, message)
    SELECT t.import_batch_id, t.line_no, e.col, e.code, e.msg
    FROM tmp_pc t
    CROSS JOIN LATERAL (VALUES
        ('brand_code',      CASE WHEN nullif(btrim(t.brand_code), '') IS NULL THEN 'REQUIRED' WHEN t.brand_id IS NULL THEN 'UNKNOWN_REF' END,
                            format('Unknown or missing brand "%s"', t.brand_code)),
        ('oem_part_number', CASE WHEN nullif(t.oem, '') IS NULL THEN 'REQUIRED' WHEN t.oem !~ '^[A-Z0-9][A-Z0-9.\-/]{2,39}$' THEN 'FORMAT' END,
                            format('Invalid OEM part number "%s"', t.oem)),
        ('description',     CASE WHEN length(coalesce(t.description, '')) < 3 THEN 'REQUIRED' END,
                            'Description is missing or shorter than 3 characters'),
        ('category_code',   CASE WHEN t.category_id IS NULL THEN 'UNKNOWN_REF' END,
                            format('Unknown category "%s"', t.category_code)),
        ('uom_code',        CASE WHEN t.uom_id IS NULL THEN 'UNKNOWN_REF' END,
                            format('Unknown unit of measure "%s"', t.uom_code)),
        ('weight_kg',       CASE WHEN nullif(btrim(t.weight_raw), '') IS NOT NULL AND t.weight_kg IS NULL THEN 'TYPE'
                                 WHEN t.weight_kg < 0 OR t.weight_kg > 999999 THEN 'RANGE' END,
                            format('Invalid weight "%s"', t.weight_raw)),
        ('unit_cost',       CASE WHEN nullif(btrim(t.cost_raw), '') IS NULL THEN 'REQUIRED'
                                 WHEN t.unit_cost IS NULL THEN 'TYPE'
                                 WHEN t.unit_cost < 0 OR t.unit_cost > 9999999999 THEN 'RANGE' END,
                            format('Invalid unit cost "%s"', t.cost_raw))
    ) AS e(col, code, msg)
    WHERE e.code IS NOT NULL
    UNION ALL
    -- duplicates inside the file: the first occurrence wins
    SELECT d.import_batch_id, d.line_no, 'oem_part_number', 'DUPLICATE', format('Duplicate of line %s', d.first_line)
    FROM (SELECT t.import_batch_id, t.line_no, t.brand_id, t.oem,
                 min(t.line_no) OVER (PARTITION BY t.brand_id, t.oem) AS first_line
          FROM tmp_pc t) d
    WHERE d.brand_id IS NOT NULL AND d.oem <> '' AND d.line_no > d.first_line;

    INSERT INTO staging.part_catalog (import_batch_id, line_no, brand_id, oem_part_number, description, category_id,
                                      uom_id, weight_kg, unit_cost, is_condition_based, is_valid)
    SELECT t.import_batch_id, t.line_no, t.brand_id, left(nullif(t.oem, ''), 40), nullif(t.description, ''),
           t.category_id, t.uom_id,
           CASE WHEN t.weight_kg BETWEEN 0 AND 999999 THEN round(t.weight_kg, 3) END,
           CASE WHEN t.unit_cost BETWEEN 0 AND 9999999999 THEN round(t.unit_cost, 2) END,
           t.condition_based,
           NOT EXISTS (SELECT 1 FROM staging.import_error e WHERE e.import_batch_id = t.import_batch_id AND e.line_no = t.line_no)
    FROM tmp_pc t;

    SELECT count(DISTINCT line_no) INTO v_errors FROM staging.import_error WHERE import_batch_id = p_batch_id;
    RETURN v_errors;
END $_$;


