--
-- Name: ensure_monthly_partitions(regclass, date, integer); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.ensure_monthly_partitions(p_parent regclass, p_from date, p_months integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_schema  text;
    v_table   text;
    v_start   date := date_trunc('month', p_from)::date;
    v_created integer := 0;
    v_name    text;
BEGIN
    SELECT n.nspname, c.relname INTO v_schema, v_table
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.oid = p_parent;

    FOR i IN 0 .. p_months - 1 LOOP
        v_name := format('%s_%s', v_table, to_char(v_start + make_interval(months => i), 'YYYYMM'));
        IF to_regclass(format('%I.%I', v_schema, v_name)) IS NULL THEN
            EXECUTE format('CREATE TABLE %I.%I PARTITION OF %s FOR VALUES FROM (%L) TO (%L)',
                           v_schema, v_name, p_parent,
                           v_start + make_interval(months => i),
                           v_start + make_interval(months => i + 1));
            v_created := v_created + 1;
        END IF;
    END LOOP;
    RETURN v_created;
END $$;


ALTER FUNCTION util.ensure_monthly_partitions(p_parent regclass, p_from date, p_months integer) OWNER TO smartspare_owner;

--
-- Name: FUNCTION ensure_monthly_partitions(p_parent regclass, p_from date, p_months integer); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.ensure_monthly_partitions(p_parent regclass, p_from date, p_months integer) IS 'Creates missing monthly RANGE partitions of a partitioned table; returns the number created.';


--
-- Name: mask_email(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.mask_email(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
    -- tomas.radzevicius@dealer.lt -> t***@d***.lt
    SELECT CASE
        WHEN p_email IS NULL THEN NULL
        WHEN position('@' IN p_email) = 0 THEN '***'
        ELSE left(split_part(p_email, '@', 1), 1) || '***@'
             || left(split_part(p_email, '@', 2), 1) || '***'
             || coalesce(substring(split_part(p_email, '@', 2) FROM '\.[^.]+$'), '')
    END
$_$;


ALTER FUNCTION util.mask_email(p_email text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION mask_email(p_email text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.mask_email(p_email text) IS 'Masks an e-mail address for display to roles without access to personal data.';


--
-- Name: mask_name(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.mask_name(p_full_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    -- Tomas Radzevičius -> T. R***
    SELECT CASE WHEN p_full_name IS NULL THEN NULL ELSE
        (SELECT string_agg(CASE WHEN ord = 1 THEN left(w, 1) || '.' ELSE left(w, 1) || '***' END, ' ' ORDER BY ord)
         FROM regexp_split_to_table(btrim(p_full_name), '\s+') WITH ORDINALITY AS t(w, ord))
    END
$$;


ALTER FUNCTION util.mask_name(p_full_name text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION mask_name(p_full_name text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.mask_name(p_full_name text) IS 'Masks a full name to initials.';


--
-- Name: mask_phone(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.mask_phone(p_phone text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    -- +370 612 34567 -> +370 *** **567  (keeps country code and last 3 digits)
    SELECT CASE WHEN p_phone IS NULL THEN NULL ELSE
        coalesce(substring(p_phone FROM '^\+\d{3}'), '') || ' *** **' || right(regexp_replace(p_phone, '\D', '', 'g'), 3)
    END
$$;


ALTER FUNCTION util.mask_phone(p_phone text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION mask_phone(p_phone text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.mask_phone(p_phone text) IS 'Masks a phone number, keeping the country code and last 3 digits.';


--
-- Name: next_document_number(text, timestamp with time zone); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.next_document_number(p_prefix text, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_year  smallint := extract(year FROM p_at AT TIME ZONE 'Europe/Vilnius');
    v_value integer;
BEGIN
    INSERT INTO util.document_counter AS c (prefix, year, last_value)
    VALUES (p_prefix, v_year, 1)
    ON CONFLICT (prefix, year) DO UPDATE SET last_value = c.last_value + 1
    RETURNING c.last_value INTO v_value;
    RETURN format('%s-%s-%s', p_prefix, v_year, lpad(v_value::text, 6, '0'));
END $$;


ALTER FUNCTION util.next_document_number(p_prefix text, p_at timestamp with time zone) OWNER TO smartspare_owner;

--
-- Name: FUNCTION next_document_number(p_prefix text, p_at timestamp with time zone); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.next_document_number(p_prefix text, p_at timestamp with time zone) IS 'Returns the next gap-less document number, e.g. SO-2026-000412. Runs inside the caller''s transaction, so a rollback releases nothing and no gap appears.';


--
-- Name: pseudonymise(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.pseudonymise(p_value text) RETURNS bytea
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_key text := current_setting('app.pseudonym_key', true);
BEGIN
    IF v_key IS NULL OR length(v_key) < 16 THEN
        RAISE EXCEPTION 'app.pseudonym_key is not set (min. 16 characters)' USING ERRCODE = 'invalid_parameter_value';
    END IF;
    RETURN public.hmac(p_value, v_key, 'sha256');
END $$;


ALTER FUNCTION util.pseudonymise(p_value text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION pseudonymise(p_value text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.pseudonymise(p_value text) IS 'Keyed HMAC-SHA256 pseudonym of an external identifier (GDPR Art. 4(5)). Key supplied per session via app.pseudonym_key.';


--
-- Name: require_app_user(); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.require_app_user() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_user uuid := util.current_app_user();
BEGIN
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'No application user in session (app.user_id is not set)' USING ERRCODE = 'SS301';
    END IF;
    RETURN v_user;
END $$;


ALTER FUNCTION util.require_app_user() OWNER TO smartspare_owner;

--
-- Name: require_role(text[]); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.require_role(VARIADIC p_roles text[]) RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_user uuid := util.require_app_user();
BEGIN
    IF NOT iam.user_has_role(v_user, VARIADIC p_roles) THEN
        RAISE EXCEPTION 'User % lacks the required role (one of %)', v_user, p_roles USING ERRCODE = 'SS301';
    END IF;
    RETURN v_user;
END $$;


ALTER FUNCTION util.require_role(VARIADIC p_roles text[]) OWNER TO smartspare_owner;

--
-- Name: FUNCTION require_role(VARIADIC p_roles text[]); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.require_role(VARIADIC p_roles text[]) IS 'Returns the session user if it has one of the roles, otherwise raises SS301 (defence in depth behind API authorisation).';


--
-- Name: trg_assign_document_number(); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.trg_assign_document_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF NEW.number IS NULL THEN
        NEW.number := util.next_document_number(TG_ARGV[0], NEW.created_at);
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION util.trg_assign_document_number() OWNER TO smartspare_owner;

--
-- Name: trg_forbid_modification(); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.trg_forbid_modification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Table %.% is append-only: % is not allowed', TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'insufficient_privilege',
              HINT = 'Post a compensating record instead of changing history.';
END $$;


ALTER FUNCTION util.trg_forbid_modification() OWNER TO smartspare_owner;

