--
-- Name: try_date(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.try_date(p text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    IF btrim(p) !~ '^\d{4}-\d{2}-\d{2}$' THEN RETURN NULL; END IF;   -- ISO 8601 only
    RETURN btrim(p)::date;
EXCEPTION WHEN others THEN
    RETURN NULL;
END $_$;


ALTER FUNCTION util.try_date(p text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION try_date(p text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.try_date(p text) IS 'Casts an ISO-8601 date (YYYY-MM-DD) to date; NULL if invalid.';


--
-- Name: try_numeric(text); Type: FUNCTION; Schema: util; Owner: smartspare_owner
--

CREATE FUNCTION util.try_numeric(p text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN replace(btrim(p), ',', '.')::numeric;
EXCEPTION WHEN others THEN
    RETURN NULL;
END $$;


ALTER FUNCTION util.try_numeric(p text) OWNER TO smartspare_owner;

--
-- Name: FUNCTION try_numeric(p text); Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON FUNCTION util.try_numeric(p text) IS 'Casts text to numeric (accepts decimal comma); NULL if not a number.';


--
-- Name: audit_log; Type: TABLE; Schema: audit; Owner: smartspare_owner
--

CREATE TABLE audit.audit_log (
    id bigint NOT NULL,
    occurred_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    user_id uuid,
    db_role name DEFAULT SESSION_USER NOT NULL,
    action character varying(10) NOT NULL,
    table_name character varying(80) NOT NULL,
    record_id character varying(80) NOT NULL,
    old_values jsonb,
    new_values jsonb,
    changed_columns text[],
    reason character varying(300),
    transaction_id bigint DEFAULT txid_current() NOT NULL,
    CONSTRAINT ck_audit_log_action CHECK (((action)::text = ANY ((ARRAY['INSERT'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying])::text[]))),
    CONSTRAINT ck_audit_log_new CHECK (((new_values IS NULL) OR (jsonb_typeof(new_values) = 'object'::text))),
    CONSTRAINT ck_audit_log_old CHECK (((old_values IS NULL) OR (jsonb_typeof(old_values) = 'object'::text))),
    CONSTRAINT ck_audit_log_shape CHECK (((((action)::text = 'INSERT'::text) AND (old_values IS NULL) AND (new_values IS NOT NULL)) OR (((action)::text = 'UPDATE'::text) AND (old_values IS NOT NULL) AND (new_values IS NOT NULL)) OR (((action)::text = 'DELETE'::text) AND (old_values IS NOT NULL) AND (new_values IS NULL))))
)
PARTITION BY RANGE (occurred_at);


ALTER TABLE audit.audit_log OWNER TO smartspare_owner;

--
-- Name: TABLE audit_log; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON TABLE audit.audit_log IS 'Immutable audit trail of state-changing operations: timestamp, user, action, previous and new values, reason (US18).';


--
-- Name: COLUMN audit_log.occurred_at; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON COLUMN audit.audit_log.occurred_at IS 'Time of the occurred event.';


--
-- Name: COLUMN audit_log.user_id; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON COLUMN audit.audit_log.user_id IS 'Application user (GUC app.user_id); NULL for background jobs.';


--
-- Name: COLUMN audit_log.old_values; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON COLUMN audit.audit_log.old_values IS 'Previous values of the changed columns only (personal data columns are excluded).';


--
-- Name: COLUMN audit_log.reason; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON COLUMN audit.audit_log.reason IS 'Business justification (GUC app.reason), e.g. reason for a manual override.';


