--
-- Name: app_user; Type: TABLE; Schema: iam; Owner: smartspare_owner
--

CREATE TABLE iam.app_user (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_name public.citext NOT NULL,
    email public.citext NOT NULL,
    full_name character varying(150) NOT NULL,
    phone character varying(30),
    password_hash text,
    security_stamp uuid DEFAULT gen_random_uuid() NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    failed_login_count smallint DEFAULT 0 NOT NULL,
    lockout_end timestamp with time zone,
    home_warehouse_id smallint,
    last_login_at timestamp with time zone,
    anonymised_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_app_user_active_has_password CHECK (((password_hash IS NOT NULL) OR (NOT is_active))),
    CONSTRAINT ck_app_user_anonymised_inactive CHECK (((anonymised_at IS NULL) OR (NOT is_active))),
    CONSTRAINT ck_app_user_email CHECK ((email OPERATOR(public.~) '^[^@\s]+@[^@\s]+\.[^@\s]+$'::public.citext)),
    CONSTRAINT ck_app_user_failed_logins CHECK (((failed_login_count >= 0) AND (failed_login_count <= 100))),
    CONSTRAINT ck_app_user_password_hash_format CHECK (((password_hash IS NULL) OR (password_hash ~ '^AQAAAA[A-Za-z0-9+/]{76,}={0,2}$'::text))),
    CONSTRAINT ck_app_user_phone CHECK (((phone IS NULL) OR ((phone)::text ~ '^\+?[0-9 ()-]{7,20}$'::text))),
    CONSTRAINT ck_app_user_user_name CHECK ((user_name OPERATOR(public.~) '^[a-z0-9._-]{3,50}$'::public.citext))
);


ALTER TABLE iam.app_user OWNER TO smartspare_owner;

