--
-- Name: v_audit_log_masked; Type: VIEW; Schema: audit; Owner: smartspare_owner
--

CREATE VIEW audit.v_audit_log_masked AS
 SELECT a.id,
    a.occurred_at,
    a.action,
    a.table_name,
    a.record_id,
    a.changed_columns,
    a.old_values,
    a.new_values,
    a.reason,
    u.user_name,
    util.mask_name((u.full_name)::text) AS actor_masked,
    a.db_role
   FROM (audit.audit_log a
     LEFT JOIN iam.app_user u ON ((u.id = a.user_id)));


ALTER VIEW audit.v_audit_log_masked OWNER TO smartspare_owner;

--
-- Name: VIEW v_audit_log_masked; Type: COMMENT; Schema: audit; Owner: smartspare_owner
--

COMMENT ON VIEW audit.v_audit_log_masked IS 'Audit trail for the sponsor / auditors with the actor''s name masked.';


