--
-- Name: v_machine_maintenance_status; Type: VIEW; Schema: fleet; Owner: smartspare_owner
--

CREATE VIEW fleet.v_machine_maintenance_status AS
 SELECT m.id AS machine_id,
    m.vin,
    b.name AS brand_name,
    mm.model_name,
    mt.code AS machine_type_code,
    c.customer_code,
    w.code AS home_warehouse_code,
    oc.code AS operating_condition_code,
    m.current_engine_hours,
    m.engine_hours_read_at,
    nd.plan_name AS next_service,
    nd.due_engine_hours AS next_service_due_hours,
    nd.remaining_hours AS next_service_remaining_hours,
    COALESCE(nd.is_overdue, false) AS is_overdue,
    ( SELECT count(*) AS count
           FROM fleet.service_order so
          WHERE ((so.machine_id = m.id) AND (so.status = ANY (ARRAY['draft'::fleet.service_order_status, 'parts_reserved'::fleet.service_order_status, 'in_progress'::fleet.service_order_status])))) AS open_service_orders
   FROM (((((((fleet.machine m
     JOIN fleet.machine_model mm ON ((mm.id = m.model_id)))
     JOIN ref.brand b ON ((b.id = mm.brand_id)))
     JOIN ref.machine_type mt ON ((mt.id = mm.machine_type_id)))
     JOIN fleet.customer c ON ((c.id = m.customer_id)))
     JOIN inventory.warehouse w ON ((w.id = m.home_warehouse_id)))
     JOIN ref.operating_condition oc ON ((oc.id = m.operating_condition_id)))
     LEFT JOIN LATERAL ( SELECT fn_maintenance_due.maintenance_plan_id,
            fn_maintenance_due.plan_name,
            fn_maintenance_due.interval_hours,
            fn_maintenance_due.effective_interval,
            fn_maintenance_due.due_engine_hours,
            fn_maintenance_due.current_engine_hours,
            fn_maintenance_due.remaining_hours,
            fn_maintenance_due.is_overdue
           FROM fleet.fn_maintenance_due(m.id, (1000000)::numeric) fn_maintenance_due(maintenance_plan_id, plan_name, interval_hours, effective_interval, due_engine_hours, current_engine_hours, remaining_hours, is_overdue)
         LIMIT 1) nd ON (true))
  WHERE (m.status = 'active'::fleet.machine_status);


ALTER VIEW fleet.v_machine_maintenance_status OWNER TO smartspare_owner;

--
-- Name: VIEW v_machine_maintenance_status; Type: COMMENT; Schema: fleet; Owner: smartspare_owner
