    CONSTRAINT ck_stock_reservation_one_source CHECK ((num_nonnulls(service_order_line_id, transfer_order_line_id) = 1)),
    CONSTRAINT ck_stock_reservation_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT ck_stock_reservation_soft_expires CHECK (((status <> 'soft'::inventory.reservation_status) OR (expires_at IS NOT NULL)))
