--
-- Name: v_service_kit_shortage; Type: VIEW; Schema: fleet; Owner: smartspare_owner
--

CREATE VIEW fleet.v_service_kit_shortage AS
 SELECT s.id AS service_order_id,
    s.number,
    s.status,
    w.code AS warehouse_code,
    l.part_id,
    p.oem_part_number,
    p.description,
    l.qty_required,
    l.qty_issued,
    COALESCE(r.held, (0)::numeric) AS qty_reserved,
    ((l.qty_required - l.qty_issued) - COALESCE(r.held, (0)::numeric)) AS qty_missing
   FROM ((((fleet.service_order s
     JOIN fleet.service_order_line l ON ((l.service_order_id = s.id)))
     JOIN catalog.part p ON ((p.id = l.part_id)))
     JOIN inventory.warehouse w ON ((w.id = s.warehouse_id)))
     LEFT JOIN LATERAL ( SELECT sum(sr.quantity) AS held
           FROM inventory.stock_reservation sr
          WHERE ((sr.service_order_line_id = l.id) AND (sr.status = ANY (ARRAY['soft'::inventory.reservation_status, 'firm'::inventory.reservation_status])))) r ON (true))
  WHERE ((s.status = ANY (ARRAY['draft'::fleet.service_order_status, 'parts_reserved'::fleet.service_order_status, 'in_progress'::fleet.service_order_status])) AND (((l.qty_required - l.qty_issued) - COALESCE(r.held, (0)::numeric)) > (0)::numeric));


ALTER VIEW fleet.v_service_kit_shortage OWNER TO smartspare_owner;

