    requested_by uuid,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    error_message text,
    CONSTRAINT ck_forecast_run_error CHECK (((status = 'failed'::forecast.run_status) = (error_message IS NOT NULL))),
    CONSTRAINT ck_forecast_run_finished CHECK (((status = 'running'::forecast.run_status) = (finished_at IS NULL))),
    CONSTRAINT ck_forecast_run_first_week_monday CHECK ((EXTRACT(isodow FROM first_week) = (1)::numeric)),
    CONSTRAINT ck_forecast_run_horizon CHECK (((horizon_weeks >= 4) AND (horizon_weeks <= 12))),
    CONSTRAINT ck_forecast_run_timeline CHECK (((finished_at IS NULL) OR (finished_at >= started_at))),
    CONSTRAINT ck_forecast_run_trigger CHECK (((triggered_by)::text = ANY ((ARRAY['scheduler'::character varying, 'user'::character varying])::text[]))),
    CONSTRAINT ck_forecast_run_user CHECK ((((triggered_by)::text = 'scheduler'::text) OR (requested_by IS NOT NULL)))
);


