--
-- Name: ml_model_version; Type: TABLE; Schema: forecast; Owner: smartspare_owner
--

CREATE TABLE forecast.ml_model_version (
    id integer NOT NULL,
    algorithm forecast.forecast_method NOT NULL,
    version_label character varying(30) NOT NULL,
    demand_class_code character varying(15),
    status forecast.model_status DEFAULT 'training'::forecast.model_status NOT NULL,
    training_from date NOT NULL,
    training_to date NOT NULL,
    holdout_from date NOT NULL,
    holdout_to date NOT NULL,
    rmsse numeric(8,4),
    mase numeric(8,4),
    mae numeric(12,4),
    rmse numeric(12,4),
    hyperparameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    artifact_uri character varying(500),
    artifact_sha256 character(64),
    trained_at timestamp with time zone,
    promoted_at timestamp with time zone,
    retired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_ml_model_version_active CHECK (((status <> 'active'::forecast.model_status) OR (promoted_at IS NOT NULL))),
    CONSTRAINT ck_ml_model_version_artifact CHECK (((algorithm <> 'fasttree'::forecast.forecast_method) OR (status = 'training'::forecast.model_status) OR (artifact_uri IS NOT NULL))),
    CONSTRAINT ck_ml_model_version_chronological_holdout CHECK (((holdout_from > training_to) AND (holdout_to >= holdout_from))),
    CONSTRAINT ck_ml_model_version_evaluated CHECK (((status = ANY (ARRAY['training'::forecast.model_status, 'rejected'::forecast.model_status])) OR ((rmsse IS NOT NULL) AND (trained_at IS NOT NULL)))),
    CONSTRAINT ck_ml_model_version_hyperparameters CHECK ((jsonb_typeof(hyperparameters) = 'object'::text)),
    CONSTRAINT ck_ml_model_version_label CHECK (((version_label)::text ~ '^v\d+\.\d+(\.\d+)?$'::text)),
    CONSTRAINT ck_ml_model_version_metrics CHECK ((((rmsse IS NULL) OR (rmsse >= (0)::numeric)) AND ((mase IS NULL) OR (mase >= (0)::numeric)) AND ((mae IS NULL) OR (mae >= (0)::numeric)) AND ((rmse IS NULL) OR (rmse >= (0)::numeric)))),
    CONSTRAINT ck_ml_model_version_sha CHECK (((artifact_sha256 IS NULL) OR (artifact_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_ml_model_version_training CHECK ((training_to > training_from))
);


