--
-- Name: recommendation; Type: TABLE; Schema: forecast; Owner: smartspare_owner
--

CREATE TABLE forecast.recommendation (
    id bigint NOT NULL,
    forecast_run_id bigint NOT NULL,
    kind forecast.recommendation_kind NOT NULL,
    warehouse_id smallint NOT NULL,
    part_id bigint NOT NULL,
    donor_warehouse_id smallint,
    supplier_id integer,
    base_demand_qty numeric(12,3) NOT NULL,
    maintenance_demand_qty numeric(12,3) NOT NULL,
    lead_time_buffer_qty numeric(12,3) NOT NULL,
    safety_stock_qty numeric(12,3) NOT NULL,
    available_qty numeric(12,3) NOT NULL,
    in_transit_qty numeric(12,3) NOT NULL,
    net_position_qty numeric(12,3) NOT NULL,
    recommended_qty numeric(12,3) NOT NULL,
    estimated_cost_eur numeric(12,2) NOT NULL,
    alternative_cost_eur numeric(12,2),
    status forecast.recommendation_status DEFAULT 'open'::forecast.recommendation_status NOT NULL,
    final_qty numeric(12,3),
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason character varying(300),
    transfer_order_id bigint,
    purchase_order_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_recommendation_accepted CHECK (((status <> 'accepted'::forecast.recommendation_status) OR (final_qty = recommended_qty))),
    CONSTRAINT ck_recommendation_cost CHECK (((estimated_cost_eur >= (0)::numeric) AND ((alternative_cost_eur IS NULL) OR (alternative_cost_eur >= (0)::numeric)))),
    CONSTRAINT ck_recommendation_decided CHECK (((status = ANY (ARRAY['open'::forecast.recommendation_status, 'expired'::forecast.recommendation_status])) = (decided_at IS NULL))),
    CONSTRAINT ck_recommendation_drivers CHECK (((base_demand_qty >= (0)::numeric) AND (maintenance_demand_qty >= (0)::numeric) AND (lead_time_buffer_qty >= (0)::numeric) AND (safety_stock_qty >= (0)::numeric) AND (available_qty >= (0)::numeric) AND (in_transit_qty >= (0)::numeric))),
    CONSTRAINT ck_recommendation_final_qty CHECK (((status <> ALL (ARRAY['accepted'::forecast.recommendation_status, 'overridden'::forecast.recommendation_status])) OR ((final_qty > (0)::numeric) AND (decided_by IS NOT NULL)))),
    CONSTRAINT ck_recommendation_kind_purchase CHECK (((kind <> 'purchase'::forecast.recommendation_kind) OR ((supplier_id IS NOT NULL) AND (donor_warehouse_id IS NULL)))),
    CONSTRAINT ck_recommendation_kind_transfer CHECK (((kind <> 'transfer'::forecast.recommendation_kind) OR ((donor_warehouse_id IS NOT NULL) AND (supplier_id IS NULL) AND (donor_warehouse_id <> warehouse_id)))),
    CONSTRAINT ck_recommendation_net_position CHECK ((net_position_qty = ((available_qty + in_transit_qty) - (((base_demand_qty + maintenance_demand_qty) + lead_time_buffer_qty) + safety_stock_qty)))),
    CONSTRAINT ck_recommendation_override CHECK (((status <> ALL (ARRAY['overridden'::forecast.recommendation_status, 'rejected'::forecast.recommendation_status])) OR (decision_reason IS NOT NULL))),
    CONSTRAINT ck_recommendation_override_qty CHECK (((status <> 'overridden'::forecast.recommendation_status) OR (final_qty <> recommended_qty))),
    CONSTRAINT ck_recommendation_qty CHECK ((recommended_qty > (0)::numeric))
);


