--

COMMENT ON COLUMN inventory.stock_movement.transfer_order_line_id IS 'Reference to inventory.transfer_order_line.';


--
-- Name: COLUMN stock_movement.purchase_order_line_id; Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON COLUMN inventory.stock_movement.purchase_order_line_id IS 'Reference to procurement.purchase_order_line.';


--
-- Name: COLUMN stock_movement.import_batch_id; Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON COLUMN inventory.stock_movement.import_batch_id IS 'Reference to raw.import_batch.';


--
-- Name: COLUMN stock_movement.external_doc_ref; Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON COLUMN inventory.stock_movement.external_doc_ref IS 'Document number in an external system (POS receipt, ERP document).';


--
-- Name: COLUMN stock_movement.created_by; Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON COLUMN inventory.stock_movement.created_by IS 'User who created the record (iam.app_user).';


--
-- Name: COLUMN stock_movement.created_at; Type: COMMENT; Schema: inventory; Owner: smartspare_owner
--

COMMENT ON COLUMN inventory.stock_movement.created_at IS 'Time the record was created.';


--
-- Name: stock_movement_202401; Type: TABLE; Schema: inventory; Owner: smartspare_owner
--

CREATE TABLE inventory.stock_movement_202401 (
    id bigint NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    warehouse_id smallint NOT NULL,
    part_id bigint NOT NULL,
    movement_type_code character varying(20) NOT NULL,
    quantity numeric(12,3) NOT NULL,
    unit_cost numeric(12,2),
    service_order_line_id bigint,
    transfer_order_line_id bigint,
    purchase_order_line_id bigint,
    import_batch_id bigint,
    external_doc_ref character varying(40),
    note character varying(300),
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_stock_movement_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT ck_stock_movement_single_document CHECK ((num_nonnulls(service_order_line_id, transfer_order_line_id, purchase_order_line_id, import_batch_id) <= 1)),
    CONSTRAINT ck_stock_movement_source_document CHECK (
CASE movement_type_code
    WHEN 'RECEIPT_PO'::text THEN (purchase_order_line_id IS NOT NULL)
    WHEN 'TRANSFER_OUT'::text THEN (transfer_order_line_id IS NOT NULL)
    WHEN 'TRANSFER_IN'::text THEN (transfer_order_line_id IS NOT NULL)
    WHEN 'ISSUE_SERVICE'::text THEN (service_order_line_id IS NOT NULL)
    WHEN 'ISSUE_SALE'::text THEN (external_doc_ref IS NOT NULL)
    WHEN 'HISTORICAL_DEMAND'::text THEN (import_batch_id IS NOT NULL)
    WHEN 'ADJUSTMENT_IN'::text THEN (note IS NOT NULL)
    WHEN 'ADJUSTMENT_OUT'::text THEN (note IS NOT NULL)
    ELSE true
END),
    CONSTRAINT ck_stock_movement_unit_cost CHECK (((unit_cost IS NULL) OR (unit_cost >= (0)::numeric)))
);


