--
-- Name: transfer_order; Type: TABLE; Schema: inventory; Owner: smartspare_owner
--

CREATE TABLE inventory.transfer_order (
    id bigint NOT NULL,
    number character varying(20) NOT NULL,
    from_warehouse_id smallint NOT NULL,
    to_warehouse_id smallint NOT NULL,
    status inventory.transfer_status DEFAULT 'proposed'::inventory.transfer_status NOT NULL,
    is_urgent boolean DEFAULT false NOT NULL,
    requested_by uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    dispatched_by uuid,
    dispatched_at timestamp with time zone,
    received_by uuid,
    received_at timestamp with time zone,
    cancel_reason character varying(300),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_transfer_order_approved CHECK (((status = ANY (ARRAY['proposed'::inventory.transfer_status, 'cancelled'::inventory.transfer_status])) OR (approved_at IS NOT NULL))),
    CONSTRAINT ck_transfer_order_cancel CHECK (((status = 'cancelled'::inventory.transfer_status) = (cancel_reason IS NOT NULL))),
    CONSTRAINT ck_transfer_order_dispatched CHECK (((status <> ALL (ARRAY['dispatched'::inventory.transfer_status, 'received'::inventory.transfer_status])) OR (dispatched_at IS NOT NULL))),
    CONSTRAINT ck_transfer_order_distinct CHECK ((from_warehouse_id <> to_warehouse_id)),
    CONSTRAINT ck_transfer_order_number CHECK (((number)::text ~ '^TR-\d{4}-\d{6}$'::text)),
    CONSTRAINT ck_transfer_order_received CHECK (((status = 'received'::inventory.transfer_status) = (received_at IS NOT NULL))),
    CONSTRAINT ck_transfer_order_timeline CHECK (((dispatched_at IS NULL) OR (dispatched_at >= approved_at))),
    CONSTRAINT ck_transfer_order_timeline2 CHECK (((received_at IS NULL) OR (received_at >= dispatched_at)))
);


ALTER TABLE inventory.transfer_order OWNER TO smartspare_owner;

