CREATE TABLE procurement.purchase_order (
    id bigint NOT NULL,
    number character varying(20) NOT NULL,
    supplier_id integer NOT NULL,
    warehouse_id smallint NOT NULL,
    status procurement.po_status DEFAULT 'draft'::procurement.po_status NOT NULL,
    is_urgent boolean DEFAULT false NOT NULL,
    urgent_reason character varying(300),
    currency_code character(3) DEFAULT 'EUR'::bpchar NOT NULL,
    total_amount numeric(14,2) DEFAULT 0 NOT NULL,
    expected_arrival_date date,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    exported_at timestamp with time zone,
    cancel_reason character varying(300),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_purchase_order_approved CHECK (((status = ANY (ARRAY['draft'::procurement.po_status, 'pending_approval'::procurement.po_status, 'cancelled'::procurement.po_status])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT ck_purchase_order_cancel CHECK (((status = 'cancelled'::procurement.po_status) = (cancel_reason IS NOT NULL))),
    CONSTRAINT ck_purchase_order_currency CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ck_purchase_order_four_eyes CHECK (((approved_by IS NULL) OR (total_amount <= (5000)::numeric) OR (approved_by <> created_by))),
    CONSTRAINT ck_purchase_order_number CHECK (((number)::text ~ '^PO-\d{4}-\d{6}$'::text)),
    CONSTRAINT ck_purchase_order_timeline CHECK (((approved_at IS NULL) OR (approved_at >= created_at))),
    CONSTRAINT ck_purchase_order_total CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT ck_purchase_order_urgent CHECK (((NOT is_urgent) OR (urgent_reason IS NOT NULL)))
);


