--
-- Name: v_in_transit; Type: VIEW; Schema: inventory; Owner: smartspare_owner
--

CREATE VIEW inventory.v_in_transit AS
 SELECT warehouse_id,
    part_id,
    sum(qty) AS in_transit_qty,
    COALESCE(sum(qty) FILTER (WHERE (src = 'transfer'::text)), (0)::numeric) AS transfer_qty,
    COALESCE(sum(qty) FILTER (WHERE (src = 'purchase'::text)), (0)::numeric) AS purchase_qty
   FROM ( SELECT o.to_warehouse_id AS warehouse_id,
            l.part_id,
            l.quantity AS qty,
            'transfer'::text AS src
           FROM (inventory.transfer_order o
             JOIN inventory.transfer_order_line l ON ((l.transfer_order_id = o.id)))
          WHERE (o.status = 'dispatched'::inventory.transfer_status)
        UNION ALL
         SELECT po.warehouse_id,
            pl.part_id,
            (pl.quantity - pl.received_qty),
            'purchase'::text
           FROM (procurement.purchase_order po
             JOIN procurement.purchase_order_line pl ON ((pl.purchase_order_id = po.id)))
          WHERE ((po.status = ANY (ARRAY['approved'::procurement.po_status, 'exported'::procurement.po_status, 'partially_received'::procurement.po_status])) AND (pl.quantity > pl.received_qty))) x
  GROUP BY warehouse_id, part_id;


