--
-- Name: v_stock_overview; Type: VIEW; Schema: inventory; Owner: smartspare_owner
--

CREATE VIEW inventory.v_stock_overview AS
 SELECT p.id AS part_id,
    b.code AS brand_code,
    p.oem_part_number,
    p.description,
    pc.code AS category_code,
    w.id AS warehouse_id,
    w.code AS warehouse_code,
    w.name AS warehouse_name,
    wp.bin_location,
    COALESCE(sb.on_hand_qty, (0)::numeric) AS on_hand_qty,
    COALESCE(sb.reserved_qty, (0)::numeric) AS reserved_qty,
    COALESCE(sb.available_qty, (0)::numeric) AS available_qty,
    COALESCE(it.in_transit_qty, (0)::numeric) AS in_transit_qty,
    wp.safety_stock_qty,
    (COALESCE(sb.available_qty, (0)::numeric) < wp.safety_stock_qty) AS below_safety_stock,
    round((COALESCE(sb.on_hand_qty, (0)::numeric) * p.unit_cost), 2) AS stock_value_eur,
    sb.last_movement_at,
    sb.updated_at AS balance_updated_at
   FROM ((((((inventory.warehouse_part wp
     JOIN catalog.part p ON ((p.id = wp.part_id)))
     JOIN ref.brand b ON ((b.id = p.brand_id)))
     JOIN ref.part_category pc ON ((pc.id = p.category_id)))
     JOIN inventory.warehouse w ON ((w.id = wp.warehouse_id)))
     LEFT JOIN inventory.stock_balance sb ON (((sb.warehouse_id = wp.warehouse_id) AND (sb.part_id = wp.part_id))))
     LEFT JOIN inventory.v_in_transit it ON (((it.warehouse_id = wp.warehouse_id) AND (it.part_id = wp.part_id))));


