--
-- Name: mv_weekly_demand; Type: MATERIALIZED VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE MATERIALIZED VIEW mart.mv_weekly_demand AS
 SELECT (date_trunc('week'::text, (m.occurred_at AT TIME ZONE 'Europe/Vilnius'::text)))::date AS week_start,
    m.warehouse_id,
    m.part_id,
    sum(m.quantity) AS demand_qty,
    count(*) AS demand_lines,
    COALESCE(sum(m.quantity) FILTER (WHERE ((m.movement_type_code)::text = 'ISSUE_SERVICE'::text)), (0)::numeric) AS service_qty
   FROM (inventory.stock_movement m
     JOIN ref.movement_type t ON ((((t.code)::text = (m.movement_type_code)::text) AND t.is_demand)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM inventory.demand_exception e
          WHERE ((e.movement_id = m.id) AND (e.movement_occurred_at = m.occurred_at)))))
  GROUP BY ((date_trunc('week'::text, (m.occurred_at AT TIME ZONE 'Europe/Vilnius'::text)))::date), m.warehouse_id, m.part_id
  WITH NO DATA;


ALTER MATERIALIZED VIEW mart.mv_weekly_demand OWNER TO smartspare_owner;

--
-- Name: MATERIALIZED VIEW mv_weekly_demand; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON MATERIALIZED VIEW mart.mv_weekly_demand IS 'Data mart: weekly demand (only non-zero weeks) per warehouse and part; source for ML training and accuracy.';


--
-- Name: mv_demand_profile; Type: MATERIALIZED VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE MATERIALIZED VIEW mart.mv_demand_profile AS
 WITH bounds AS (
         SELECT ((date_trunc('week'::text, (now() AT TIME ZONE 'Europe/Vilnius'::text)))::date - 7) AS last_week
        ), s AS (
         SELECT d.warehouse_id,
            d.part_id,
            min(d.week_start) AS first_week,
            max(d.week_start) AS last_demand_week,
            count(*) AS nonzero_weeks,
            sum(d.demand_qty) AS total_qty,
            avg(d.demand_qty) AS mean_nonzero,
            stddev_pop(d.demand_qty) AS sd_nonzero
           FROM (mart.mv_weekly_demand d
             CROSS JOIN bounds b)
          WHERE ((d.week_start >= (b.last_week - (7 * 103))) AND (d.week_start <= b.last_week))
          GROUP BY d.warehouse_id, d.part_id
        ), k AS (
         SELECT s.warehouse_id,
            s.part_id,
            s.first_week,
            s.last_demand_week,
            s.nonzero_weeks,
            s.total_qty,
            s.mean_nonzero,
            s.sd_nonzero,
            b.last_week,
            (((b.last_week - s.first_week) / 7) + 1) AS periods,
            round((((((b.last_week - s.first_week) / 7) + 1))::numeric / (s.nonzero_weeks)::numeric), 3) AS adi,
            round(COALESCE(power((s.sd_nonzero / NULLIF(s.mean_nonzero, (0)::numeric)), (2)::numeric), (0)::numeric), 3) AS cv2
           FROM (s
             CROSS JOIN bounds b)
        )
 SELECT warehouse_id,
    part_id,
    first_week,
    last_week,
    last_demand_week,
    periods,
    nonzero_weeks,
    total_qty,
    adi,
    cv2,
    forecast.fn_classify_demand(adi, cv2) AS demand_class_code,
    now() AS computed_at
   FROM k
  WITH NO DATA;


