--
-- Name: v_data_quality; Type: VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE VIEW mart.v_data_quality AS
 WITH ledger AS (
         SELECT m.warehouse_id,
            m.part_id,
            sum(((t.balance_sign)::numeric * m.quantity)) AS qty
           FROM (inventory.stock_movement m
             JOIN ref.movement_type t ON (((t.code)::text = (m.movement_type_code)::text)))
          WHERE (t.balance_sign <> 0)
          GROUP BY m.warehouse_id, m.part_id
        ), holds AS (
         SELECT stock_reservation.warehouse_id,
            stock_reservation.part_id,
            sum(stock_reservation.quantity) AS qty
           FROM inventory.stock_reservation
          WHERE (stock_reservation.status = ANY (ARRAY['soft'::inventory.reservation_status, 'firm'::inventory.reservation_status]))
          GROUP BY stock_reservation.warehouse_id, stock_reservation.part_id
        )
 SELECT 'stock_balance = SUM(ledger)'::text AS check_name,
    ( SELECT count(*) AS count
           FROM (inventory.stock_balance b
             FULL JOIN ledger l USING (warehouse_id, part_id))
          WHERE (COALESCE(b.on_hand_qty, (0)::numeric) <> COALESCE(l.qty, (0)::numeric))) AS failed_rows
UNION ALL
 SELECT 'reserved_qty = SUM(active reservations)'::text AS check_name,
    ( SELECT count(*) AS count
           FROM (inventory.stock_balance b
             FULL JOIN holds h USING (warehouse_id, part_id))
          WHERE (COALESCE(b.reserved_qty, (0)::numeric) <> COALESCE(h.qty, (0)::numeric))) AS failed_rows
UNION ALL
 SELECT 'PO total = SUM(lines)'::text AS check_name,
    ( SELECT count(*) AS count
           FROM procurement.purchase_order po
          WHERE (po.total_amount <> ( SELECT COALESCE(sum(l.line_amount), (0)::numeric) AS "coalesce"
                   FROM procurement.purchase_order_line l
                  WHERE (l.purchase_order_id = po.id)))) AS failed_rows
UNION ALL
 SELECT 'machine hours = last reading'::text AS check_name,
    ( SELECT count(*) AS count
           FROM (fleet.machine m
             JOIN LATERAL ( SELECT r_1.reading_hours
                   FROM fleet.engine_hours_reading r_1
                  WHERE (r_1.machine_id = m.id)
                  ORDER BY r_1.read_at DESC
                 LIMIT 1) r ON (true))
          WHERE (m.current_engine_hours <> r.reading_hours)) AS failed_rows
UNION ALL
 SELECT 'active parts without supplier'::text AS check_name,
    ( SELECT count(*) AS count
           FROM catalog.part p
          WHERE (p.is_active AND (NOT (EXISTS ( SELECT 1
                   FROM catalog.supplier_part sp
                  WHERE (sp.part_id = p.id)))))) AS failed_rows
UNION ALL
 SELECT 'duplicate demand rows in staging (loaded)'::text AS check_name,
    ( SELECT count(*) AS count
           FROM ( SELECT demand_history.row_hash
                   FROM staging.demand_history
                  WHERE (demand_history.is_valid AND (NOT demand_history.is_duplicate))
                  GROUP BY demand_history.row_hash
                 HAVING (count(*) > 1)) d) AS failed_rows
UNION ALL
 SELECT 'expired soft reservations still active'::text AS check_name,
    ( SELECT count(*) AS count
           FROM inventory.stock_reservation
          WHERE ((stock_reservation.status = 'soft'::inventory.reservation_status) AND (stock_reservation.expires_at < (now() - '01:00:00'::interval)))) AS failed_rows;


ALTER VIEW mart.v_data_quality OWNER TO smartspare_owner;

--
-- Name: VIEW v_data_quality; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON VIEW mart.v_data_quality IS 'Automated reconciliation checks (ledger vs. balance, reservations, PO totals, odometer, duplicates). Expected: all failed_rows = 0.';


--
-- Name: v_forecast_accuracy; Type: VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE VIEW mart.v_forecast_accuracy AS
 WITH pairs AS (
         SELECT f.forecast_run_id,
            pr.demand_class_code,
            f.forecast_qty,
            COALESCE(d.demand_qty, (0)::numeric) AS actual_qty
           FROM ((forecast.demand_forecast f
             LEFT JOIN mart.mv_weekly_demand d ON (((d.warehouse_id = f.warehouse_id) AND (d.part_id = f.part_id) AND (d.week_start = f.week_start))))
             LEFT JOIN mart.mv_demand_profile pr ON (((pr.warehouse_id = f.warehouse_id) AND (pr.part_id = f.part_id))))
          WHERE ((f.week_start + 7) <= (date_trunc('week'::text, (now() AT TIME ZONE 'Europe/Vilnius'::text)))::date)
        )
 SELECT forecast_run_id,
    COALESCE(demand_class_code, 'ALL'::character varying) AS demand_class_code,
    count(*) AS points,
    round(avg(abs((forecast_qty - actual_qty))), 4) AS mae,
    round(sqrt(avg(power((forecast_qty - actual_qty), (2)::numeric))), 4) AS rmse,
    round(avg((forecast_qty - actual_qty)), 4) AS bias
   FROM pairs
  GROUP BY GROUPING SETS ((forecast_run_id, demand_class_code), (forecast_run_id));


ALTER VIEW mart.v_forecast_accuracy OWNER TO smartspare_owner;

--
-- Name: VIEW v_forecast_accuracy; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON VIEW mart.v_forecast_accuracy IS 'Forecast vs. actual per run and demand class (MAE, RMSE, bias) for completed weeks.';


