--
-- Name: v_kpi_dead_stock; Type: VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE VIEW mart.v_kpi_dead_stock AS
 SELECT COALESCE(w.code, 'NETWORK'::character varying) AS warehouse_code,
    round(sum((sb.on_hand_qty * p.unit_cost)), 2) AS stock_value_eur,
    round(sum((sb.on_hand_qty * p.unit_cost)) FILTER (WHERE (NOT x.has_demand)), 2) AS dead_stock_value_eur,
    round((((100)::numeric * COALESCE(sum((sb.on_hand_qty * p.unit_cost)) FILTER (WHERE (NOT x.has_demand)), (0)::numeric)) / NULLIF(sum((sb.on_hand_qty * p.unit_cost)), (0)::numeric)), 1) AS dead_stock_ratio_pct,
    10.0 AS target_pct
   FROM (((inventory.stock_balance sb
     JOIN catalog.part p ON ((p.id = sb.part_id)))
     JOIN inventory.warehouse w ON ((w.id = sb.warehouse_id)))
     CROSS JOIN LATERAL ( SELECT (EXISTS ( SELECT 1
                   FROM (inventory.stock_movement m
                     JOIN ref.movement_type t ON ((((t.code)::text = (m.movement_type_code)::text) AND t.is_demand)))
                  WHERE ((m.part_id = sb.part_id) AND (m.warehouse_id = sb.warehouse_id) AND (m.occurred_at >= (now() - '1 year'::interval))))) AS has_demand) x)
  WHERE (sb.on_hand_qty > (0)::numeric)
  GROUP BY ROLLUP(w.code);


ALTER VIEW mart.v_kpi_dead_stock OWNER TO smartspare_owner;

--
-- Name: VIEW v_kpi_dead_stock; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON VIEW mart.v_kpi_dead_stock IS 'KPI-05: value share of stock without any demand in 12 months, per hub and for the network (target <= 10 %).';


--
-- Name: v_kpi_recommendation_acceptance; Type: VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE VIEW mart.v_kpi_recommendation_acceptance AS
 SELECT (date_trunc('month'::text, decided_at))::date AS month,
    kind,
    count(*) AS decided,
    count(*) FILTER (WHERE (status = 'accepted'::forecast.recommendation_status)) AS accepted,
    count(*) FILTER (WHERE (status = 'overridden'::forecast.recommendation_status)) AS overridden,
    count(*) FILTER (WHERE (status = 'rejected'::forecast.recommendation_status)) AS rejected,
    round(((100.0 * (count(*) FILTER (WHERE (status = 'accepted'::forecast.recommendation_status)))::numeric) / (count(*))::numeric), 1) AS acceptance_rate_pct,
    80.0 AS target_pct
   FROM forecast.recommendation r
  WHERE (decided_at IS NOT NULL)
  GROUP BY ROLLUP(((date_trunc('month'::text, decided_at))::date), kind);


ALTER VIEW mart.v_kpi_recommendation_acceptance OWNER TO smartspare_owner;

--
-- Name: VIEW v_kpi_recommendation_acceptance; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON VIEW mart.v_kpi_recommendation_acceptance IS 'KPI-04: share of recommendations accepted without change (target >= 80 %); ROLLUP gives subtotals.';


