--
-- Name: v_ml_training_set; Type: VIEW; Schema: mart; Owner: smartspare_owner
--

CREATE VIEW mart.v_ml_training_set AS
 SELECT g.warehouse_id,
    g.part_id,
    g.week_start,
    (EXTRACT(week FROM g.week_start))::smallint AS iso_week,
    ac.season_phase_code,
    ac.seasonal_weight,
    p.brand_id,
    p.category_id,
    g.demand_class_code,
    COALESCE(d.demand_qty, (0)::numeric) AS demand_qty,
    lag(COALESCE(d.demand_qty, (0)::numeric), 1) OVER w AS lag_1,
    lag(COALESCE(d.demand_qty, (0)::numeric), 2) OVER w AS lag_2,
    lag(COALESCE(d.demand_qty, (0)::numeric), 4) OVER w AS lag_4,
    lag(COALESCE(d.demand_qty, (0)::numeric), 52) OVER w AS lag_52,
    avg(COALESCE(d.demand_qty, (0)::numeric)) OVER (w ROWS BETWEEN 4 PRECEDING AND 1 PRECEDING) AS rolling_mean_4,
    avg(COALESCE(d.demand_qty, (0)::numeric)) OVER (w ROWS BETWEEN 13 PRECEDING AND 1 PRECEDING) AS rolling_mean_13,
    count(d.demand_qty) OVER (w ROWS BETWEEN 13 PRECEDING AND 1 PRECEDING) AS nonzero_weeks_13
   FROM (((( SELECT pr.warehouse_id,
            pr.part_id,
            pr.demand_class_code,
            (gs.gs)::date AS week_start
           FROM (mart.mv_demand_profile pr
             CROSS JOIN LATERAL generate_series((pr.first_week)::timestamp with time zone, (pr.last_week)::timestamp with time zone, '7 days'::interval) gs(gs))) g
     JOIN catalog.part p ON ((p.id = g.part_id)))
     JOIN ref.agro_calendar_week ac ON (((ac.iso_week)::numeric = EXTRACT(week FROM g.week_start))))
     LEFT JOIN mart.mv_weekly_demand d ON (((d.warehouse_id = g.warehouse_id) AND (d.part_id = g.part_id) AND (d.week_start = g.week_start))))
  WINDOW w AS (PARTITION BY g.warehouse_id, g.part_id ORDER BY g.week_start);


ALTER VIEW mart.v_ml_training_set OWNER TO smartspare_owner;

--
-- Name: VIEW v_ml_training_set; Type: COMMENT; Schema: mart; Owner: smartspare_owner
--

COMMENT ON VIEW mart.v_ml_training_set IS 'ML.NET training/inference features: dense weekly series with season, lags (1,2,4,52) and rolling means (window functions).';


