--
-- Name: v_privilege_findings; Type: VIEW; Schema: util; Owner: smartspare_owner
--

CREATE VIEW util.v_privilege_findings AS
 SELECT 'app_read cannot SELECT'::text AS finding,
    (((n.nspname)::text || '.'::text) || (c.relname)::text) AS object_name
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((n.nspname = ANY (ARRAY['ref'::name, 'catalog'::name, 'inventory'::name, 'fleet'::name, 'procurement'::name, 'forecast'::name, 'mart'::name])) AND (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char", 'v'::"char", 'm'::"char"])) AND (NOT c.relispartition) AND (NOT has_table_privilege('app_read'::name, c.oid, 'SELECT'::text)))
UNION ALL
 SELECT 'app_read can read personal data column'::text AS finding,
    ('iam.app_user.'::text || col.col) AS object_name
   FROM unnest(ARRAY['full_name'::text, 'email'::text, 'phone'::text, 'password_hash'::text]) col(col)
  WHERE has_column_privilege('app_read'::name, 'iam.app_user'::text, col.col, 'SELECT'::text)
UNION ALL
 SELECT 'function executable by PUBLIC'::text AS finding,
    ((p.oid)::regprocedure)::text AS object_name
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = ANY (ARRAY['util'::name, 'iam'::name, 'catalog'::name, 'inventory'::name, 'fleet'::name, 'procurement'::name, 'forecast'::name, 'audit'::name, 'raw'::name, 'staging'::name, 'mart'::name, 'ref'::name])) AND has_function_privilege('public'::name, p.oid, 'EXECUTE'::text))
UNION ALL
 SELECT 'SECURITY DEFINER without search_path'::text AS finding,
    ((p.oid)::regprocedure)::text AS object_name
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE (p.prosecdef AND (n.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name])) AND (NOT (EXISTS ( SELECT 1
           FROM unnest(p.proconfig) cfg(cfg)
          WHERE (cfg.cfg ~~ 'search_path=%'::text)))))
UNION ALL
 SELECT 'privileged application login'::text AS finding,
    (r.rolname)::text AS object_name
   FROM pg_roles r
  WHERE ((r.rolname = ANY (ARRAY['smartspare_api'::name, 'smartspare_jobs'::name, 'smartspare_reporting'::name, 'smartspare_migrator'::name])) AND (r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb))
UNION ALL
 SELECT 'write privilege on protected table'::text AS finding,
    ((r.r || ' -> '::text) || t.t) AS object_name
   FROM unnest(ARRAY['app_write'::text, 'app_ml'::text, 'app_read'::text]) r(r),
    unnest(ARRAY['inventory.stock_balance'::text, 'audit.audit_log'::text, 'inventory.stock_reservation'::text]) t(t)
  WHERE (has_table_privilege((r.r)::name, t.t, 'UPDATE'::text) OR has_table_privilege((r.r)::name, t.t, 'DELETE'::text))
UNION ALL
 SELECT 'UPDATE/DELETE privilege on ledger'::text AS finding,
    r.r AS object_name
   FROM unnest(ARRAY['app_write'::text, 'app_ml'::text, 'app_read'::text, 'app_admin'::text]) r(r)
  WHERE (has_table_privilege((r.r)::name, 'inventory.stock_movement'::text, 'UPDATE'::text) OR has_table_privilege((r.r)::name, 'inventory.stock_movement'::text, 'DELETE'::text));


ALTER VIEW util.v_privilege_findings OWNER TO smartspare_owner;

--
-- Name: VIEW v_privilege_findings; Type: COMMENT; Schema: util; Owner: smartspare_owner
--

COMMENT ON VIEW util.v_privilege_findings IS 'Security self-check: must return zero rows. Executed by the test suite after every migration.';


