--
-- Name: v_purchase_order_overview _RETURN; Type: RULE; Schema: procurement; Owner: smartspare_owner
--

CREATE OR REPLACE VIEW procurement.v_purchase_order_overview AS
 SELECT po.id,
    po.number,
    s.code AS supplier_code,
    s.name AS supplier_name,
    w.code AS warehouse_code,
    po.status,
    po.is_urgent,
    po.total_amount,
    po.currency_code,
    count(l.id) AS line_count,
    COALESCE(sum(l.received_qty), (0)::numeric) AS received_qty,
    COALESCE(sum(l.quantity), (0)::numeric) AS ordered_qty,
    cu.user_name AS created_by_user,
    au.user_name AS approved_by_user,
    (po.total_amount > (5000)::numeric) AS requires_four_eyes,
    po.created_at,
    po.approved_at,
    po.expected_arrival_date
   FROM (((((procurement.purchase_order po
     JOIN catalog.supplier s ON ((s.id = po.supplier_id)))
     JOIN inventory.warehouse w ON ((w.id = po.warehouse_id)))
     JOIN iam.app_user cu ON ((cu.id = po.created_by)))
     LEFT JOIN iam.app_user au ON ((au.id = po.approved_by)))
     LEFT JOIN procurement.purchase_order_line l ON ((l.purchase_order_id = po.id)))
  GROUP BY po.id, s.code, s.name, w.code, cu.user_name, au.user_name;


